fn checkTrailingWhitespace(
    src: []const u8,
    errors: *std.ArrayList(ParseError),
) !void {
    if (src.len == 0) return;
    var i = src.len - 1;
    while (i > 0 and (src[i] == ' ' or src[i] == '\n' or
                      src[i] == '\t' or src[i] == '\r')) : (i -= 1) {}
