use std::collections::HashMap;

// ---------- 词法 ----------
#[derive(Debug, Clone, Copy, PartialEq)]
enum Tok {
    Zero, One, Half, Dot,
    LParen, RParen, LAngle, RAngle,
    LBrace, RBrace, LBracket, RBracket,
    Slash, Eof,
}

#[derive(Debug, Clone)]
struct Token { kind: Tok, pos: usize }

fn lex(src: &str) -> Vec<Token> {
    let mut out = Vec::new();
    let chars: Vec<char> = src.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        let kind = match c {
            '0' | '０' => Tok::Zero,
            '1' => Tok::One,
            '½' => Tok::Half,
            '.' => Tok::Dot,
            '(' => Tok::LParen,
            ')' => Tok::RParen,
            '<' => Tok::LAngle,
            '>' => Tok::RAngle,
            '{' | '｛' => Tok::LBrace,
            '}' | '｝' => Tok::RBrace,
            '[' | '［' => Tok::LBracket,
            ']' | '］' => Tok::RBracket,
            '/' => Tok::Slash,
            ' ' | '\n' | '\t' | '\r' => { i += 1; continue; }
            _ => { i += 1; continue; }
        };
        out.push(Token { kind, pos: i });
        i += 1;
    }
    out.push(Token { kind: Tok::Eof, pos: i });
    out
}

// ---------- AST ----------
#[derive(Debug, Clone, PartialEq)]
enum Kind { Zero, One, Half, Include, Proxy, Multi, Bracket }

#[derive(Debug, Clone)]
struct Node {
    kind: Kind,
    children: Vec<Node>,
    pos: usize,
    parallel: bool,
}

// ---------- Parser ----------
struct Parser { toks: Vec<Token>, pos: usize }

impl Parser {
    fn peek(&self) -> Tok { self.toks[self.pos].kind }
    fn bump(&mut self) -> Token { let t = self.toks[self.pos].clone(); self.pos += 1; t }

    // 解析一行：多个表达式并排，全部收进来
    fn parse_line(&mut self) -> Vec<Node> {
        let mut nodes = Vec::new();
        while self.peek() != Tok::Eof {
            match self.parse_atom() {
                Ok(n) => nodes.push(n),
                Err(_) => { self.bump(); }
            }
        }
        nodes
    }

    fn parse_atom(&mut self) -> Result<Node, String> {
        let t = self.bump();
        match t.kind {
            Tok::Zero => Ok(Node { kind: Kind::Zero, children: vec![], pos: t.pos, parallel: false }),
            Tok::One => Ok(Node { kind: Kind::One, children: vec![], pos: t.pos, parallel: false }),
            Tok::Half => Ok(Node { kind: Kind::Half, children: vec![], pos: t.pos, parallel: false }),
            Tok::LParen => {
                let mut n = self.parse_group(Tok::RParen, Kind::Include, t.pos)?;
                if n.children.is_empty() && self.peek() == Tok::Slash {
                    self.bump();
                    n.parallel = true;
                }
                Ok(n)
            }
            Tok::LAngle => self.parse_group(Tok::RAngle, Kind::Proxy, t.pos),
            Tok::LBrace => self.parse_group(Tok::RBrace, Kind::Multi, t.pos),
            Tok::LBracket => self.parse_group(Tok::RBracket, Kind::Bracket, t.pos),
            _ => Err(format!("意外 token {:?}", t.kind)),
        }
    }

    fn parse_group(&mut self, close: Tok, kind: Kind, pos: usize) -> Result<Node, String> {
        let mut children = Vec::new();
        while self.peek() != close {
            if self.peek() == Tok::Eof { return Err("未闭合".into()); }
            children.push(self.parse_atom()?);
        }
        self.bump();
        Ok(Node { kind, children, pos, parallel: false })
    }
}

// ---------- 统计 ----------
struct LineStats {
    first: Option<Kind>,        // 第一段最外层
    last: Option<Kind>,         // 最后一段最外层
    first_inner: Option<Kind>,  // 第一段里第一个子节点
    last_inner: Option<Kind>,   // 最后一段里第一个子节点
    last_slash: bool,           // 最后一段带 /
    pending: usize,             // 待填姑娘位（空括号）
    filled: Vec<Kind>,          // 已填姑娘位的内容
    proxy_count: usize,         // 尖号个数
    community_count: usize,     // 大括号/中括号个数
    depth: usize,               // 最大嵌套深度
}

fn count_pending_filled(node: &Node, pending: &mut usize, filled: &mut Vec<Kind>) {
    match node.kind {
        Kind::Include => {
            if node.children.is_empty() {
                *pending += 1;
            } else {
                for c in &node.children {
                    if c.kind == Kind::Zero || c.kind == Kind::One {
                        filled.push(c.kind.clone());
                    }
                }
            }
        }
        _ => {}
    }
    for c in &node.children {
        count_pending_filled(c, pending, filled);
    }
}

fn count_kinds(node: &Node, proxy: &mut usize, community: &mut usize) {
    match node.kind {
        Kind::Proxy => *proxy += 1,
        Kind::Multi | Kind::Bracket => *community += 1,
        _ => {}
    }
    for c in &node.children {
        count_kinds(c, proxy, community);
    }
}

fn max_depth(node: &Node) -> usize {
    let d = node.children.iter().map(max_depth).max().unwrap_or(0);
    d + 1
}

fn analyze_line(nodes: &[Node]) -> LineStats {
    let mut s = LineStats {
        first: None, last: None,
        first_inner: None, last_inner: None,
        last_slash: false,
        pending: 0, filled: vec![],
        proxy_count: 0, community_count: 0, depth: 0,
    };
    if nodes.is_empty() { return s; }

    s.first = Some(nodes[0].kind.clone());
    s.first_inner = nodes[0].children.first().map(|c| c.kind.clone());

    let last = nodes.last().unwrap();
    s.last = Some(last.kind.clone());
    s.last_inner = last.children.first().map(|c| c.kind.clone());
    s.last_slash = last.parallel;

    for n in nodes {
        count_pending_filled(n, &mut s.pending, &mut s.filled);
        count_kinds(n, &mut s.proxy_count, &mut s.community_count);
        let d = max_depth(n);
        if d > s.depth { s.depth = d; }
    }
    s
}

// ---------- 中文输出 ----------
fn kind_cn(k: &Kind) -> &'static str {
    match k {
        Kind::Zero => "0（包含路公约数）",
        Kind::One => "1（代理路公约数）",
        Kind::Half => "½（显影半份）",
        Kind::Include => "圆括号（包含壳）",
        Kind::Proxy => "尖号（代理壳）",
        Kind::Multi => "大括号（共同体）",
        Kind::Bracket => "中括号（共同体）",
    }
}

fn who_goes(first: &Option<Kind>, last: &Option<Kind>) -> &'static str {
    let f = matches!(first, Some(Kind::One));
    let l = matches!(last, Some(Kind::One));
    let f0 = matches!(first, Some(Kind::Zero));
    let l0 = matches!(last, Some(Kind::Zero));

    if f || l { "你" }
    else if f0 && l0 { "妻子" }
    else { "你" }
}

fn print_line(idx: usize, stats: &LineStats) {
    println!("第 {} 行：", idx + 1);

    // 第一段
    if let Some(ref k) = stats.first {
        println!("  第一段最外层：{}", kind_cn(k));
        if let Some(ref ik) = stats.first_inner {
            println!("    里面第一个：{}", kind_cn(ik));
        }
    }

    // 最后一段
    if let Some(ref k) = stats.last {
        println!("  最后一段最外层：{}", kind_cn(k));
        if let Some(ref ik) = stats.last_inner {
            println!("    里面第一个：{}", kind_cn(ik));
        }
        if stats.last_slash {
            println!("    带 /：平行世界声明");
        }
    }

    // 谁去
    println!("  谁去平行世界：{}", who_goes(&stats.first, &stats.last));

    // 姑娘位
    println!("  待填姑娘位：{} 个", stats.pending);
    if stats.filled.is_empty() {
        println!("  已填姑娘位：0 个");
    } else {
        let contents: Vec<&str> = stats.filled.iter().map(|k| match k {
            Kind::Zero => "0",
            Kind::One => "1",
            _ => "?",
        }).collect();
        println!("  已填姑娘位：{} 个（内容：{}）", stats.filled.len(), contents.join(","));
    }

    println!("  尖号个数：{}，共同体个数：{}，最大深度：{}",
        stats.proxy_count, stats.community_count, stats.depth);
    println!();
}

