#[derive(Debug, Clone)]
struct Node {
    kind: Kind,
    children: Vec<Node>,
    pos: usize,
    parallel: bool,
    is_self: bool,   // 是否本体
    is_field_for: Vec<usize>,  // 对哪些节点是场
}

// ---------- Parser ----------
struct Parser { toks: Vec<Token>, pos: usize }

impl Parser {
    fn peek(&self) -> Tok { self.toks[self.pos].kind }
    fn bump(&mut self) -> Token { let t = self.toks[self.pos].clone(); self.pos += 1; t }

    fn parse_line(&mut self) -> Vec<Node> {
        let mut nodes = Vec::new();
        while self.peek() != Tok::Eof {
            match self.parse_atom() {
                Ok(n) => nodes.push(n),
                Err(_) => { self.bump(); }
            }
        }
        nodes
    }

    fn parse_atom(&mut self) -> Result<Node, String> {
        let t = self.bump();
        match t.kind {
            Tok::Zero => Ok(Node { kind: Kind::Zero, children: vec![], pos: t.pos, parallel: false, is_self: true, is_field_for: vec![] }),
            Tok::One => Ok(Node { kind: Kind::One, children: vec![], pos: t.pos, parallel: false, is_self: true, is_field_for: vec![] }),
            Tok::Half => Ok(Node { kind: Kind::Half, children: vec![], pos: t.pos, parallel: false, is_self: true, is_field_for: vec![] }),
            Tok::Sun => Ok(Node { kind: Kind::Sun, children: vec![], pos: t.pos, parallel: false, is_self: true, is_field_for: vec![] }),
            Tok::LParen => {
                let mut n = self.parse_group(Tok::RParen, Kind::Include, t.pos)?;
