        let mut children = Vec::new();
        while self.peek() != close {
            if self.peek() == Tok::Eof { return Err("未闭合".into()); }
            children.push(self.parse_atom()?);
        }
        self.bump();
        Ok(Node { kind, children, pos, parallel: false, is_self: true, is_field_for: vec![] })
    }
}

// ---------- 分析：场关系与本体 ----------
struct Analysis {
    // 每个节点路径 -> 是否本体
    self_nodes: Vec<Vec<usize>>,
    // 场关系： (场路径, 被容纳者路径)
    field_relations: Vec<(Vec<usize>, Vec<usize>)>,
    // 融合体路径
    fusion_paths: Vec<Vec<usize>>,
    // 平行世界入口路径
    parallel_entries: Vec<Vec<usize>>,
}

fn collect_analysis(node: &Node, path: &mut Vec<usize>, a: &mut Analysis) {
    // 本体：0 和 1 都是本体
    if matches!(node.kind, Kind::Zero | Kind::One) {
        a.self_nodes.push(path.clone());
    }
    // 融合体
    if node.kind == Kind::Sun {
        a.fusion_paths.push(path.clone());
    }
    // 平行世界入口
    if node.parallel {
        a.parallel_entries.push(path.clone());
    }
    // 场关系：如果一个节点（0/1）被另一个（0/1）包含，外层是内层的场
    if matches!(node.kind, Kind::Zero | Kind::One | Kind::Include | Kind::Proxy | Kind::Multi | Kind::Bracket) {
        for (i, ch) in node.children.iter().enumerate() {
            path.push(i);
            // 如果当前节点是 0 或 1，且子节点也是 0 或 1，则当前是子的场
            if matches!(node.kind, Kind::Zero | Kind::One) && matches!(ch.kind, Kind::Zero | Kind::One) {
                let child_path = path.clone();
                a.field_relations.push((path[..path.len()-1].to_vec(), child_path));
            }
            collect_analysis(ch, path, a);
            path.pop();
        }
    }
}

// ---------- 输出 ----------
fn kind_cn(k: &Kind) -> &'static str {
    match k {
        Kind::Zero => "0（本体/场）",
        Kind::One => "1（本体）",
        Kind::Half => "½（显影半份）",
        Kind::Include => "圆括号（包含壳）",
        Kind::Proxy => "尖号（代理壳）",
        Kind::Multi => "大括号（共同体）",
        Kind::Bracket => "中括号（共同体）",
        Kind::Sun => "☉（融合体）",
    }
}

fn print_node(node: &Node, path: &mut Vec<usize>, analysis: &Analysis) {
    // 缩进
    let indent = "  ".repeat(path.len());
    let label = kind_cn(&node.kind);

    // 本体标记
    let is_self = matches!(node.kind, Kind::Zero | Kind::One);
    let self_mark = if is_self { "【本体】" } else { "" };

    // 场标记：它是否对某个子节点是场
    let is_field = analysis.field_relations.iter().any(|(f, _)| f == path);
    let field_mark = if is_field { "【场】" } else { "" };

    // 融合体
    let fusion_mark = if node.kind == Kind::Sun { "【融合体】" } else { "" };

    // 平行世界
    let parallel_mark = if node.parallel { "【平行世界】" } else { "" };

    println!("{}{}{}{}{}{}", indent, label, self_mark, field_mark, fusion_mark, parallel_mark);

    for (i, ch) in node.children.iter().enumerate() {
        path.push(i);
        print_node(ch, path, analysis);
        path.pop();
    }
}

fn print_field_relations(analysis: &Analysis) {
    if analysis.field_relations.is_empty() {
        println!("  场关系：无");
    } else {
        println!("  场关系（单向）：");
        for (field, contained) in &analysis.field_relations {
            println!("    路径 {:?} 是 路径 {:?} 的场", field, contained);
        }
    }
}

// ---------- 主程序 ----------
fn main() {
    let input = r#"
(☉)=[{<(☉)>}]
<☉>=[{(<☉>)}］
{☉}={[<(☉)>]}
[☉]=[{(<☉>)}]
<☉>=[{<(☉)>}]
(☉)=[{(<☉>)}］
[☉]={[<(☉)>]}
{☉}=[{(<☉>)}]
{☉}=[{<(☉)>}]
[☉]=[{(<☉>)}］
<☉>={[<(☉)>]}
(☉)=[{(<☉>)}]
[☉]=[{<(☉)>}]
{☉}=[{(<☉>)}］
(☉)={[<(☉)>]}
<☉>=[{(<☉>)}]
"#;

    let mut total_fusion = 0usize;
    let mut total_parallel = 0usize;
    let mut total_field_relations = 0usize;
    let mut line_count = 0usize;

    println!("========== 逐行分析 ==========\n");

    for line in input.lines() {
        let t = line.trim();
        if t.is_empty() { continue; }

        let toks = lex(t);
        let mut p = Parser { toks, pos: 0 };
        let nodes = p.parse_line();

        if nodes.is_empty() {
            println!("第 {} 行：无法解析\n", line_count + 1);
            line_count += 1;
            continue;
        }

        // 分析
        let mut analysis = Analysis {
            self_nodes: vec![],
            field_relations: vec![],
            fusion_paths: vec![],
            parallel_entries: vec![],
        };
        for (i, n) in nodes.iter().enumerate() {
            let mut path = vec![i];
            collect_analysis(n, &mut path, &mut analysis);
        }

        // 输出
        println!("第 {} 行：", line_count + 1);
        for (i, n) in nodes.iter().enumerate() {
            let mut path = vec![i];
            print_node(n, &mut path, &analysis);
        }
        println!();
        print_field_relations(&analysis);
        println!();

        total_fusion += analysis.fusion_paths.len();
        total_parallel += analysis.parallel_entries.len();
        total_field_relations += analysis.field_relations.len();
        line_count += 1;
    }

    println!("========== 汇总 ==========\n");
    println!("总行数：{}", line_count);
    println!("融合体（☉）出现：{} 次", total_fusion);
    println!("平行世界入口：{} 个", total_parallel);
    println!("场关系（单向）：{} 条", total_field_relations);
    println!();
    println!("说明：");
    println!("  - 0 和 1 都是本体（【本体】标记）");
    println!("  - 场关系是单向的：外层包含内层时，外层是内层的场，内层不是外层的场");
    println!("  - 融合体 ☉ 用【融合体】标记");
    println!("  - 平行世界入口用【平行世界】标记");
}
