use std::collections::HashMap;

// ---------- 词法 ----------
#[derive(Debug, Clone, Copy, PartialEq)]
enum Tok {
    Zero, One, Half, Dot,
    LParen, RParen, LAngle, RAngle,
    LBrace, RBrace, LBracket, RBracket,
    Slash, Sun, Eq, Eof,
}

#[derive(Debug, Clone)]
struct Token { kind: Tok, pos: usize }

fn lex(src: &str) -> Vec<Token> {
    let mut out = Vec::new();
    let chars: Vec<char> = src.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        let kind = match c {
            '0' | '０' => Tok::Zero,
            '1' => Tok::One,
            '½' => Tok::Half,
            '.' => Tok::Dot,
            '(' => Tok::LParen,
            ')' => Tok::RParen,
            '<' => Tok::LAngle,
            '>' => Tok::RAngle,
            '{' | '｛' => Tok::LBrace,
            '}' | '｝' => Tok::RBrace,
            '[' | '［' => Tok::LBracket,
            ']' | '］' => Tok::RBracket,
            '/' => Tok::Slash,
            '☉' => Tok::Sun,
            '=' => Tok::Eq,
            ' ' | '\n' | '\t' | '\r' => { i += 1; continue; }
            _ => { i += 1; continue; }
        };
        out.push(Token { kind, pos: i });
        i += 1;
    }
    out.push(Token { kind: Tok::Eof, pos: i });
    out
}

// ---------- AST ----------
#[derive(Debug, Clone, PartialEq)]
enum Kind { Zero, One, Half, Include, Proxy, Multi, Bracket, Sun, Eq }

#[derive(Debug, Clone)]
struct Node {
    kind: Kind,
    children: Vec<Node>,
    pos: usize,
    parallel: bool,
}

// ---------- Parser ----------
struct Parser { toks: Vec<Token>, pos: usize }

impl Parser {
    fn peek(&self) -> Tok { self.toks[self.pos].kind }
    fn bump(&mut self) -> Token { let t = self.toks[self.pos].clone(); self.pos += 1; t }

    fn parse_line(&mut self) -> Vec<Node> {
        let mut nodes = Vec::new();
        while self.peek() != Tok::Eof {
            match self.parse_atom() {
                Ok(n) => nodes.push(n),
                Err(_) => { self.bump(); }
            }
        }
        nodes
    }

    fn parse_atom(&mut self) -> Result<Node, String> {
        let t = self.bump();
        match t.kind {
            Tok::Zero => Ok(Node { kind: Kind::Zero, children: vec![], pos: t.pos, parallel: false }),
            Tok::One => Ok(Node { kind: Kind::One, children: vec![], pos: t.pos, parallel: false }),
            Tok::Half => Ok(Node { kind: Kind::Half, children: vec![], pos: t.pos, parallel: false }),
            Tok::Sun => Ok(Node { kind: Kind::Sun, children: vec![], pos: t.pos, parallel: false }),
            Tok::Eq => Ok(Node { kind: Kind::Eq, children: vec![], pos: t.pos, parallel: false }),
            Tok::LParen => {
                let mut n = self.parse_group(Tok::RParen, Kind::Include, t.pos)?;
                if n.children.is_empty() && self.peek() == Tok::Slash {
                    self.bump();
                    n.parallel = true;
                }
                Ok(n)
            }
            Tok::LAngle => self.parse_group(Tok::RAngle, Kind::Proxy, t.pos),
            Tok::LBrace => self.parse_group(Tok::RBrace, Kind::Multi, t.pos),
            Tok::LBracket => self.parse_group(Tok::RBracket, Kind::Bracket, t.pos),
            _ => Err(format!("意外 token {:?}", t.kind)),
        }
    }

    fn parse_group(&mut self, close: Tok, kind: Kind, pos: usize) -> Result<Node, String> {
        let mut children = Vec::new();
        while self.peek() != close {
            if self.peek() == Tok::Eof { return Err("未闭合".into()); }
            children.push(self.parse_atom()?);
        }
        self.bump();
        Ok(Node { kind, children, pos, parallel: false })
    }
}

// ---------- 统计 ----------
#[derive(Debug, Clone)]
struct LineStats {
    // 符号出现次数
    symbol_counts: HashMap<String, usize>,
    // 总节点数
    total_nodes: usize,
    // 最大嵌套深度
    max_depth: usize,
    // 镜像对（左右两个 ☉ 互为镜像）
    mirror_pairs: usize,
    // 镜像奇偶
    mirror_parity: String,
    // 梯度方向
    gradient_direction: String,
    // 融合体路径
    fusion_paths: Vec<Vec<usize>>,
    // 融合体奇偶态
    fusion_parity: Vec<String>,
    // 平行世界入口
    parallel_entries: Vec<Vec<usize>>,
    // 场关系
    field_relations: Vec<(Vec<usize>, Vec<usize>)>,
}

fn count_symbols(node: &Node, counts: &mut HashMap<String, usize>, total: &mut usize) {
    let name = match node.kind {
        Kind::Zero => "0",
        Kind::One => "1",
        Kind::Half => "½",
        Kind::Sun => "☉",
        Kind::Include => "()",
        Kind::Proxy => "<>",
        Kind::Multi => "{}",
        Kind::Bracket => "[]",
        Kind::Eq => "=",
    };
    *counts.entry(name.to_string()).or_insert(0) += 1;
    *total += 1;
    for c in &node.children {
        count_symbols(c, counts, total);
    }
}

fn max_depth(node: &Node) -> usize {
    let d = node.children.iter().map(max_depth).max().unwrap_or(0);
    d + 1
}

fn collect_fusion_paths(node: &Node, path: &mut Vec<usize>, out: &mut Vec<Vec<usize>>) {
    if node.kind == Kind::Sun {
        out.push(path.clone());
    }
    for (i, c) in node.children.iter().enumerate() {
        path.push(i);
        collect_fusion_paths(c, path, out);
        path.pop();
    }
}

fn collect_field_relations(
    node: &Node,
    path: &mut Vec<usize>,
    out: &mut Vec<(Vec<usize>, Vec<usize>)>,
) {
    if matches!(node.kind, Kind::Zero | Kind::One) {
        for (i, c) in node.children.iter().enumerate() {
            if matches!(c.kind, Kind::Zero | Kind::One) {
                path.push(i);
                out.push((path[..path.len()-1].to_vec(), path.clone()));
                path.pop();
            }
        }
    }
    for (i, c) in node.children.iter().enumerate() {
        path.push(i);
        collect_field_relations(c, path, out);
        path.pop();
    }
}

fn analyze_line(nodes: &[Node]) -> LineStats {
    let mut s = LineStats {
        symbol_counts: HashMap::new(),
        total_nodes: 0,
        max_depth: 0,
        mirror_pairs: 0,
        mirror_parity: "偶".into(),
        gradient_direction: "平移".into(),
        fusion_paths: vec![],
        fusion_parity: vec![],
        parallel_entries: vec![],
        field_relations: vec![],
    };

    // 统计符号、深度
    for n in nodes {
        count_symbols(n, &mut s.symbol_counts, &mut s.total_nodes);
        let d = max_depth(n);
        if d > s.max_depth { s.max_depth = d; }
    }

    // 收集融合体路径
    for (i, n) in nodes.iter().enumerate() {
        let mut path = vec![i];
        collect_fusion_paths(n, &mut path, &mut s.fusion_paths);
    }

    // 收集平行世界
    for (i, n) in nodes.iter().enumerate() {
        let mut path = vec![i];
        collect_parallel(n, &mut path, &mut s.parallel_entries);
    }

    // 收集场关系
    for (i, n) in nodes.iter().enumerate() {
        let mut path = vec![i];
        collect_field_relations(n, &mut path, &mut s.field_relations);
    }

    // 镜像数：左右两个 ☉ 互为镜像
    // 简化：如果一行有 ≥2 个 ☉，每两个算一对
    let sun_count = *s.symbol_counts.get("☉").unwrap_or(&0);
    if sun_count >= 2 {
        s.mirror_pairs = sun_count * (sun_count - 1) / 2;
    }
    s.mirror_parity = if s.mirror_pairs % 2 == 0 { "偶".into() } else { "奇".into() };

    // 梯度方向：比较左右两边的最大深度
    if nodes.len() >= 2 {
        let left_depth = max_depth(&nodes[0]);
        let right_depth = max_depth(&nodes[nodes.len()-1]);
        s.gradient_direction = if left_depth > right_depth {
            "收缩（左深右浅）".into()
        } else if right_depth > left_depth {
            "拉伸（左浅右深）".into()
        } else {
            "平移（左右等深）".into()
        };
    }

    // 融合体奇偶态：每个 ☉ 覆盖的镜像对叠加
    // 简化：每个 ☉ 单独算，奇数对=奇，偶数对=偶
    for _ in &s.fusion_paths {
        s.fusion_parity.push(if s.mirror_pairs % 2 == 0 { "偶".into() } else { "奇".into() });
    }

    s
}

fn collect_parallel(node: &Node, path: &mut Vec<usize>, out: &mut Vec<Vec<usize>>) {
    if node.parallel {
        out.push(path.clone());
    }
    for (i, c) in node.children.iter().enumerate() {
        path.push(i);
        collect_parallel(c, path, out);
        path.pop();
    }
}

// ---------- 输出 ----------
fn print_stats(s: &LineStats) {
    println!("  镜像数：{} 对（奇偶：{}）", s.mirror_pairs, s.mirror_parity);
    println!("  梯度方向：{}", s.gradient_direction);
    println!("  融合体：{} 个", s.fusion_paths.len());
    if !s.fusion_parity.is_empty() {
        println!("  融合体奇偶态：{}", s.fusion_parity.join(", "));
    }
    println!("  平行世界入口：{} 个", s.parallel_entries.len());
    println!("  场关系（单向）：{} 条", s.field_relations.len());

    // 存在频率
    println!("  存在频率：");
    let mut sorted: Vec<_> = s.symbol_counts.iter().collect();
    sorted.sort_by(|a, b| b.1.cmp(a.1));
    for (sym, cnt) in sorted {
        let pct = if s.total_nodes > 0 {
            *cnt as f64 / s.total_nodes as f64 * 100.0
        } else { 0.0 };
        println!("    {}：{} 次（{:.1}%）", sym, cnt, pct);
    }
    println!("  总节点数：{}", s.total_nodes);
    println!("  最大深度：{}", s.max_depth);
}

// ---------- 主程序 ----------
fn main() {
    let input = r#"
(☉)=[{<(☉)>}]
<☉>=[{(<☉>)}］
{☉}={[<(☉)>]}
[☉]=[{(<☉>)}]
<☉>=[{<(☉)>}]
(☉)=[{(<☉>)}］
[☉]={[<(☉)>]}
{☉}=[{(<☉>)}]
{☉}=[{<(☉)>}]
[☉]=[{(<☉>)}］
<☉>={[<(☉)>]}
(☉)=[{(<☉>)}]
[☉]=[{<(☉)>}]
{☉}=[{(<☉>)}］
(☉)={[<(☉)>]}
<☉>=[{(<☉>)}]
"#;

    let mut total_mirror_pairs = 0usize;
    let mut total_fusion = 0usize;
    let mut total_parallel = 0usize;
    let mut total_field = 0usize;
    let mut line_count = 0usize;

    println!("========== 逐行分析 ==========\n");

    for line in input.lines() {
        let t = line.trim();
        if t.is_empty() { continue; }

        let toks = lex(t);
        let mut p = Parser { toks, pos: 0 };
        let nodes = p.parse_line();

        if nodes.is_empty() {
            println!("第 {} 行：无法解析\n", line_count + 1);
            line_count += 1;
            continue;
        }

        let s = analyze_line(&nodes);
        println!("第 {} 行：", line_count + 1);
        print_stats(&s);
        println!();

        total_mirror_pairs += s.mirror_pairs;
        total_fusion += s.fusion_paths.len();
        total_parallel += s.parallel_entries.len();
        total_field += s.field_relations.len();
        line_count += 1;
    }

    println!("========== 汇总 ==========\n");
    println!("总行数：{}", line_count);
    println!("镜像对总数：{} 对", total_mirror_pairs);
    println!("融合体（☉）总数：{} 个", total_fusion);
    println!("平行世界入口：{} 个", total_parallel);
    println!("场关系（单向）：{} 条", total_field);
    println!();
    println!("说明：");
    println!("  - 镜像数：两个 ☉ 互为镜像算一对，公式 n(n-1)/2");
