```zig
const std = @import("std");

const Vec3 = struct { x: f64, y: f64, z: f64 };

const 中心 = struct {
    id: u32,
    位置: Vec3,
    点数: u32,
    连接: std.ArrayList(u32),
};

const 星形图案 = struct {
    中心id: u32,
    外点: []Vec3,  // 外点
    花瓣线: [][]Vec3, // 从中心到每个外点的线
    内点: []Vec3, // 内角点（连接相邻外点）
};

// 生成n角星形
fn 生成星形(allocator, 中心位置, 外半径, 内半径, 点数) !星形图案 {
    var 外点 = try allocator.alloc(Vec3, 点数);
    var 花瓣线 = try allocator.alloc([]Vec3, 点数);

    for (0..点数) |i| {
        const 角度 = 2.0 * PI * i / 点数;
        外点[i] = .{
            .x = 中心位置.x + 外半径 * cos(角度),
            .y = 中心位置.y + 外半径 * sin(角度),
            .z = 中心位置.z,
        };

        // 花瓣：从中心到外点
        花瓣线[i] = try allocator.alloc(Vec3, 2);
        花瓣线[i][0] = 中心位置;
        花瓣线[i][1] = 外点[i];
    }

    return .{ .中心id = 0, .外点 = 外点, .花瓣线 = 花瓣线 };
}

// 多个中心：在圆上排列
fn 生成多中心(allocator, 中心数, 环半径, 每个中心的点数) ![]中心 {
    var 中心s = try allocator.alloc(中心, 中心数);
    for (0..中心数) |i| {
        const 角度 = 2.0 * PI * i / 中心数;
        中心s[i] = .{
            .id = i,
            .位置 = .{
                .x = 环半径 * cos(角度),
                .y = 环半径 * sin(角度),
                .z = 0,
            },
            .点数 = 每个中心的点数,
            .连接 = std.ArrayList(u32).init(allocator),
        };
    }
    // 连接中心：每个中心连接到相邻中心
    for (0..中心数) |i| {
        try 中心s[i].连接.append((i + 1) % 中心数);
        try 中心s[i].连接.append((i - 1 + 中心数) % 中心数);
    }
    return 中心s;
}
```

