```zig
const std = @import("std");
const PI = std.math.pi;

const Vec3 = struct { x: f64, y: f64, z: f64 };

// 星形的一个“花瓣”：从中心到外点的一条线
const 花瓣 = struct {
    中心: Vec3,
    外点: Vec3,
};

// 中心之间的轨迹
const 轨迹 = struct {
    从: Vec3,
    到: Vec3,
};

const 星形结构 = struct {
    中心s: []Vec3,           // 所有中心的位置
    花瓣: []花瓣,            // 所有花瓣
    轨迹: []轨迹,            // 所有轨迹
    外点: []Vec3,            // 所有外点
};

fn 生成对称星形(
    allocator,
    中心数: u32,
    每中心花瓣数: u32,
    中心环半径: f64,
    外半径: f64,
) !星形结构 {
    var 中心s = try allocator.alloc(Vec3, 中心数);
    var 花瓣s = std.ArrayList(花瓣).init(allocator);
    var 轨迹s = std.ArrayList(轨迹).init(allocator);
    var 外点s = std.ArrayList(Vec3).init(allocator);

    // 1. 将中心放在圆上（N重对称）
    for (0..中心数) |i| {
        const 角度 = 2.0 * PI * i / 中心数;
        中心s[i] = .{
            .x = 中心环半径 * cos(角度),
            .y = 中心环半径 * sin(角度),
            .z = 0,
        };
    }

    // 2. 为每个中心生成花瓣
    for (0..中心数) |i| {
        for (0..每中心花瓣数) |j| {
            const 花瓣角度 = 2.0 * PI * j / 每中心花瓣数;
            const 外点 = Vec3{
                .x = 中心s[i].x + 外半径 * cos(花瓣角度),
                .y = 中心s[i].y + 外半径 * sin(花瓣角度),
                .z = 0,
            };
            try 花瓣s.append(.{ .中心 = 中心s[i], .外点 = 外点 });
            try 外点s.append(外点);
        }
    }

    // 3. 中心之间的轨迹（编织：连接到下一个中心）
    for (0..中心数) |i| {
        const 下一个 = (i + 1) % 中心数;
        try 轨迹s.append(.{ .从 = 中心s[i], .到 = 中心s[下一个] });
    }

    return .{
        .中心s = 中心s,
        .花瓣 = try 花瓣s.toOwnedSlice(),
        .轨迹 = try 轨迹s.toOwnedSlice(),
        .外点 = try 外点s.toOwnedSlice(),
    };
}
```

