```zig
const std = @import("std");
const PI = std.math.pi;

const Vec3 = struct {
    x: f64, y: f64, z: f64,

    fn distance(a: Vec3, b: Vec3) f64 {
        const dx = a.x - b.x;
        const dy = a.y - b.y;
        const dz = a.z - b.z;
        return @sqrt(dx*dx + dy*dy + dz*dz);
    }
};

const 星形 = struct {
    中心: Vec3,
    花瓣: [][]Vec3,      // 每个花瓣是一条线段 [2]Vec3
    外点: []Vec3,        // 每个花瓣的外点
    连接: []u32,         // 连接到其他中心的索引
};

const 多中心结构 = struct {
    中心s: []Vec3,
    星形s: []星形,
    轨迹: [][]Vec3,      // 中心之间的轨迹线段
};

fn 生成多中心结构(
    allocator: std.mem.Allocator,
    中心数: u32,
    每中心花瓣数: u32,
    中心圆半径: f64,
    花瓣外半径: f64,
    编织步长: u32,  // 编织连接：连接到 (i+步长)%中心数
) !多中心结构 {
    var 中心s = try allocator.alloc(Vec3, 中心数);

    // 1. 将中心均匀放在圆上（中心数重对称）
    for (0..中心数) |i| {
        const 角度 = 2.0 * PI * @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(中心数));
        中心s[i] = .{
            .x = 中心圆半径 * @cos(角度),
            .y = 中心圆半径 * @sin(角度),
            .z = 0,
        };
    }

    // 2. 为每个中心生成花瓣
    var 星形s = try allocator.alloc(星形, 中心数);
    for (0..中心数) |i| {
        var 花瓣s = try allocator.alloc([]Vec3, 每中心花瓣数);
        var 外点s = try allocator.alloc(Vec3, 每中心花瓣数);

        for (0..每中心花瓣数) |j| {
            const 花瓣角度 = 2.0 * PI * @as(f64, @floatFromInt(j)) / @as(f64, @floatFromInt(每中心花瓣数));
            const 外点 = Vec3{
                .x = 中心s[i].x + 花瓣外半径 * @cos(花瓣角度),
                .y = 中心s[i].y + 花瓣外半径 * @sin(花瓣角度),
                .z = 0,
            };
            外点s[j] = 外点;

            // 花瓣线段：中心 → 外点
            花瓣s[j] = try allocator.alloc(Vec3, 2);
            花瓣s[j][0] = 中心s[i];
            花瓣s[j][1] = 外点;
        }

        // 编织连接：连接到 (i+步长)%中心数
        var 连接s = try allocator.alloc(u32, 2); // 前向和后向
        连接s[0] = (i + 编织步长) % 中心数;
        连接s[1] = (i + 中心数 - 编织步长) % 中心数;

        星形s[i] = .{
            .中心 = 中心s[i],
            .花瓣 = 花瓣s,
            .外点 = 外点s,
            .连接 = 连接s,
        };
    }

    // 3. 生成中心之间的轨迹（编织）
    var 轨迹s = std.ArrayList([]Vec3).init(allocator);
    for (0..中心数) |i| {
        const 目标 = (i + 编织步长) % 中心数;
        // 避免重复轨迹
        if (i < 目标 or 目标 == 0 and i > 0) {
            if (i != 目标) {
                const 线段 = try allocator.alloc(Vec3, 2);
                线段[0] = 中心s[i];
                线段[1] = 中心s[目标];
                try 轨迹s.append(线段);
            }
        }
    }

    return .{
        .中心s = 中心s,
        .星形s = 星形s,
        .轨迹 = try 轨迹s.toOwnedSlice(),
    };
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // 7个中心，每个5片花瓣，中心圆半径2.0，花瓣外半径1.0
    // 编织步长：2（即中心i连接到中心(i+2)%7）
    var 结构 = try 生成多中心结构(
