            .{i, 轨迹[0].x, 轨迹[0].y, 轨迹[1].x, 轨迹[1].y});
    }

    // 计算对称性：如果7个中心均匀分布，结构具有7重旋转对称
    // 检查：旋转2π/7是否映射到自身
    std.debug.print("\n对称性: 7重旋转对称（中心均匀分布在圆上）\n", .{});

