```zig
const std = @import("std");
const PI = std.math.pi;

const Vec3 = struct {
    x: f64, y: f64, z: f64,
};

// 中心：一个中心，有花瓣（从中心到外点的线）
const 中心 = struct {
    位置: Vec3,
    花瓣: [][]Vec3,  // 每个花瓣是一条线段（2个点）
};

// 多中心结构
const 多中心结构 = struct {
    中心s: []中心,
    外点s: []Vec3,       // 所有外点
    轨迹: [][]Vec3,      // 中心之间的轨迹
};

fn 生成多中心结构(
    allocator: std.mem.Allocator,
    中心数: u32,          // M个中心
    每中心花瓣数: u32,    // 每个中心K条花瓣
    中心环半径: f64,      // 中心排列的圆半径
    外点半径: f64,        // 外点距离中心的范围
    编织步长: u32,        // 编织连接步长
) !多中心结构 {
    var 中心s = try allocator.alloc(中心, 中心数);
    var 外点s = std.ArrayList(Vec3).init(allocator);
    var 轨迹s = std.ArrayList([]Vec3).init(allocator);

    // 1. 均匀放置中心
    for (0..中心数) |i| {
        const 角度 = 2.0 * PI * @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(中心数));
        中心s[i].位置 = .{
            .x = 中心环半径 * @cos(角度),
            .y = 中心环半径 * @sin(角度),
            .z = 0,
        };

        // 2. 为这个中心生成花瓣
        var 花瓣s = try allocator.alloc([]Vec3, 每中心花瓣数);
        for (0..每中心花瓣数) |j| {
            // 花瓣角度：围绕中心均匀分布
            const 花瓣角度 = 2.0 * PI * @as(f64, @floatFromInt(j)) / @as(f64, @floatFromInt(每中心花瓣数));

            // 外点位置：中心位置 + 外点半径 * 方向
            const 外点 = Vec3{
                .x = 中心s[i].位置.x + 外点半径 * @cos(花瓣角度),
                .y = 中心s[i].位置.y + 外点半径 * @sin(花瓣角度),
                .z = 0,
            };

            // 花瓣线：中心 → 外点
            花瓣s[j] = try allocator.alloc(Vec3, 2);
            花瓣s[j][0] = 中心s[i].位置;
            花瓣s[j][1] = 外点;

            try 外点s.append(外点);
        }
        中心s[i].花瓣 = 花瓣s;
    }

    // 3. 中心之间的轨迹（编织）
    for (0..中心数) |i| {
        const 目标 = (i + 编织步长) % 中心数;
        if (i != 目标) {
            // 检查是否已有反向轨迹
            var 重复 = false;
            for (轨迹s.items) |已有| {
                if (已有[0].x == 中心s[目标].位置.x and
                    已有[0].y == 中心s[目标].位置.y and
                    已有[1].x == 中心s[i].位置.x and
                    已有[1].y == 中心s[i].位置.y) {
                    重复 = true;
                    break;
                }
            }
            if (!重复) {
                const 线段 = try allocator.alloc(Vec3, 2);
                线段[0] = 中心s[i].位置;
                线段[1] = 中心s[目标].位置;
                try 轨迹s.append(线段);
            }
        }
    }

    return .{
        .中心s = 中心s,
        .外点s = try 外点s.toOwnedSlice(),
        .轨迹 = try 轨迹s.toOwnedSlice(),
    };
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // 7个中心，每个5片花瓣
    // 中心均匀分布在半径2.0的圆上
    // 每个中心的花瓣向外延伸1.0
