    std.debug.print("\n对称性分析:\n", .{});
    std.debug.print("  中心数=7（质数），对称阶数: 1, 7\n", .{});
    std.debug.print("  每个中心花瓣数=5，花瓣对称阶数: 1, 5\n", .{});
    std.debug.print("  整体对称: 7重旋转对称\n", .{});

