```

**“红”的义项**：
- 义项 0：颜色红（范畴：颜色）
- 义项 1：红火、受欢迎（范畴：状态）
- 义项 2：流血、革命（范畴：政治/身体）

**“花”的义项**：
- 义项 0：花朵（范畴：植物）
- 义项 1：花钱（范畴：消费）
- 义项 2：眼花（范畴：感知）

### 二、语境线索

语境至少给三样：

- **周边词**：前后出现的词。
- **当前范畴**：对话/句子的主题范畴。
- **最近激活节点**：刚刚被提到或注意到的节点。

```zig
const Context = struct {
    nearby_words: []const []const u8, // 周边词
    current_category: ?u32,           // 当前主题范畴
    recent_nodes: []const u64,        // 最近激活节点 id
};
```

### 三、消歧函数

```zig
fn disambiguate(
    node: SemNode,
    ctx: Context,
    graph: *SemGraph,
) ?u32 {
    if (node.senses.len == 0) return null;
    if (node.senses.len == 1) return node.senses[0].id;

    var best_id: ?u32 = null;
    var best_score: f64 = -1e9;

    for (node.senses) |s| {
        var score: f64 = s.weight;

        // 1. 范畴匹配：当前范畴和义项范畴一致，加分
        if (ctx.current_category) |cat| {
            if (s.category == cat) score += 2.0;
        }

        // 2. 关键词匹配：周边词命中义项关键词，加分
        for (ctx.nearby_words) |w| {
            for (s.keywords) |kw| {
                if (std.mem.eql(u8, w, kw)) score += 1.5;
            }
        }

        // 3. 最近激活节点：和最近节点有关系的义项，加分
        for (ctx.recent_nodes) |rid| {
            if (graph.hasEdge(rid, node.id, s.category)) score += 1.0;
        }

        if (score > best_score) {
            best_score = score;
            best_id = s.id;
        }
    }
    return best_id;
}
```

### 四、组合时先消歧，再组合

```zig
fn combineWithContext(
    a: SemNode,
    b: SemNode,
    ctx: Context,
    graph: *SemGraph,
    edge_strength: f64,
    allocator: std.mem.Allocator,
) !CombineResult {
    // 1. 先消歧
    const a_sense = disambiguate(a, ctx, graph);
    const b_sense = disambiguate(b, ctx, graph);

    if (a_sense == null or b_sense == null) {
        return .{ .success = false, .new_node = null, .rule_name = "",
                  .strength = 0, .reason = "义项无法确定" };
    }

    // 2. 用消歧后的义项查组合规则
    const sense_a = a.senses[a_sense.?];
    const sense_b = b.senses[b_sense.?];

    // 3. 规则匹配时，额外检查范畴兼容
    for (rules) |r| {
        if (r.left == a.node_type and r.right == b.node_type) {
            // 范畴兼容检查：两个义项范畴是否冲突
            if (!categoryCompatible(sense_a.category, sense_b.category)) {
                continue;
            }

            const new_hanzi = try std.fmt.allocPrint(allocator, "{s}{s}", .{ a.hanzi, b.hanzi });
            return .{
                .success = true,
                .new_node = SemNode{
                    .id = 0, .hanzi = new_hanzi, .node_type = r.result,
                    .senses = &.{}, .active_sense = null,
                },
                .rule_name = r.name,
                .strength = edge_strength * sense_a.weight * sense_b.weight,
                .reason = "消歧后规则匹配",
            };
        }
    }

    return .{ .success = false, .new_node = null, .rule_name = "",
              .strength = 0, .reason = "消歧后无匹配规则" };
}

fn categoryCompatible(a: u32, b: u32) bool {
    // 简化：同范畴或任一方为 0（通用）算兼容
    return a == b or a == 0 or b == 0;
}
```

