```zig
const std = @import("std");

/// 干涉边：领导 → 下属，分派任务，完成任务有奖励
pub const InterferenceEdge = struct {
    from: u64,           // 领导 id
    to: u64,             // 下属 id
    task_strength: f64,  // 任务强度 0~1
    reward: f64,         // 完成任务后的工资
    level_required: u32, // 等级要求
};

/// 准入门槛：教育成本 ≥ 阈值，才获得资格
pub const Gate = struct {
    education_cost: f64, // 已投入的教育时间成本
    threshold: f64,      // 准入门槛
    qualified: bool,     // 是否通过

    pub fn evaluate(self: *Gate) void {
        self.qualified = self.education_cost >= self.threshold;
    }
};

/// 退出成本：离开代价 vs 替代方案收益
pub const ExitCost = struct {
    leave_cost: f64,       // 离开代价
    alternative_gain: f64, // 替代方案收益
    locked: bool,          // 是否被锁定（不敢离开）

    pub fn evaluate(self: *ExitCost) void {
        self.locked = self.leave_cost > self.alternative_gain;
    }
};

/// 个人状态：等级、匮乏程度、是否在系统内
pub const Person = struct {
    id: u64,
    level: u32,
    need: f64,       // 匮乏程度 0~1，越高越需要奖励
    in_system: bool,
};

/// 判断：是否接受干涉（等级匹配 + 奖励 > 匮乏）
pub fn shouldAcceptInterference(edge: InterferenceEdge, person: Person) bool {
    if (person.level < edge.level_required) return false;
    return edge.reward > person.need;
}

/// 判断：是否留下（资格通过 + 被锁定）
pub fn shouldStay(gate: Gate, exit: ExitCost) bool {
    return gate.qualified and exit.locked;
}

/// 系统的完整判断：接受干涉 + 留下
pub const SystemVerdict = struct {
    accept: bool,      // 接受干涉
    stay: bool,        // 留下
    reason: []const u8,
};

pub fn evaluate(
    edge: InterferenceEdge,
    person: Person,
    gate: Gate,
    exit: ExitCost,
) SystemVerdict {
    const accept = shouldAcceptInterference(edge, person);
    const stay = shouldStay(gate, exit);

    var reason_buf: [128]u8 = undefined;
    const reason = std.fmt.bufPrint(&reason_buf, "accept={}, stay={}", .{ accept, stay }) catch "eval";

    return .{ .accept = accept, .stay = stay, .reason = reason };
}

// 测试
test "qualified and locked" {
    var gate = Gate{ .education_cost = 100, .threshold = 50, .qualified = false };
    gate.evaluate();
    try std.testing.expect(gate.qualified);

    var exit = ExitCost{ .leave_cost = 80, .alternative_gain = 30, .locked = false };
    exit.evaluate();
    try std.testing.expect(exit.locked);

    try std.testing.expect(shouldStay(gate, exit));
}

test "accept interference" {
    const edge = InterferenceEdge{ .from = 1, .to = 2, .task_strength = 0.8, .reward = 0.7, .level_required = 2 };
    const p = Person{ .id = 2, .level = 3, .need = 0.5, .in_system = true };
    try std.testing.expect(shouldAcceptInterference(edge, p));

    const p_low = Person{ .id = 3, .level = 1, .need = 0.5, .in_system = false };
    try std.testing.expect(!shouldAcceptInterference(edge, p_low));
}

test "need too high" {
    const edge = InterferenceEdge{ .from = 1, .to = 2, .task_strength = 0.5, .reward = 0.3, .level_required = 1 };
    const p = Person{ .id = 2, .level = 1, .need = 0.8, .in_system = true };
    try std.testing.expect(!shouldAcceptInterference(edge, p));
}
