const std = @import("std");
const attention_mod = @import("attention.zig");
const TriMode = attention_mod.TriMode;
const triWeight = attention_mod.triWeight;

/// 磁悬浮参数
pub const MaglevParams = struct {
    质量: f64 = 1.0,
    重力: f64 = 9.8,
    电磁系数k: f64 = 0.01,
    目标间隙: f64 = 0.01,
    初始间隙: f64 = 0.02,
    初始速度: f64 = 0.0,
    Kp: f64 = 5000.0,
    Kd: f64 = 200.0,
    基础电流: f64 = 1.0,
    电流上限: f64 = 10.0,
    时间步长: f64 = 0.0001,
    总时间: f64 = 0.5,
    三角数模式: TriMode = .conserve,
};

/// 仿真结果
pub const MaglevResult = struct {
    最终间隙: f64,
    最终速度: f64,
    失稳: bool,
    失稳原因: []const u8,
    步数: u32,
    最大电流: f64,
};

/// PD 控制律：电流 = 基础 + 三角数权重 × (Kp·误差 + Kd·速度)
pub fn pdCurrent(
    p: MaglevParams,
    z: f64,
    v: f64,
    step: u32,
) f64 {
    const 误差 = z - p.目标间隙;
    const w = triWeight(step, p.三角数模式);
    var 电流 = p.基础电流 + w * (p.Kp * 误差 + p.Kd * v);
    if (电流 < 0) 电流 = 0;
    if (电流 > p.电流上限) 电流 = p.电流上限;
    return 电流;
}

/// 电磁力：F = k·i²/z²
pub fn electromagneticForce(p: MaglevParams, 电流: f64, z: f64) f64 {
    if (z <= 0) return 0;
    return p.电磁系数k * 电流 * 电流 / (z * z);
}

/// 磁悬浮仿真：单自由度，PD 控制
pub fn simulateMaglev(allocator: std.mem.Allocator, p: MaglevParams) !MaglevResult {
    _ = allocator;
    var z = p.初始间隙;
    var v = p.初始速度;
    var t: f64 = 0;
    var step: u32 = 0;
    var 最大电流: f64 = 0;

    while (t <= p.总时间) : (t += p.时间步长) {
        step += 1;

        const 电流 = pdCurrent(p, z, v, step);
        if (电流 > 最大电流) 最大电流 = 电流;

        const F = electromagneticForce(p, 电流, z);
        const 加速度 = p.重力 - F / p.质量;

        v += 加速度 * p.时间步长;
        z += v * p.时间步长;

        // 撞地或飞走
        if (z <= 0) {
            return .{ .最终间隙 = z, .最终速度 = v, .失稳 = true,
                      .失稳原因 = "撞地", .步数 = step, .最大电流 = 最大电流 };
        }
        if (z > 0.1) {
            return .{ .最终间隙 = z, .最终速度 = v, .失稳 = true,
                      .失稳原因 = "飞走", .步数 = step, .最大电流 = 最大电流 };
        }
    }

    return .{ .最终间隙 = z, .最终速度 = v, .失稳 = false,
              .失稳原因 = "", .步数 = step, .最大电流 = 最大电流 };
}

/// 轨迹插值：从起点到终点，按极坐标线性插值
pub fn interpolatePolar(
    allocator: std.mem.Allocator,
    r0: f64, theta0: f64,
    r1: f64, theta1: f64,
    steps: u32,
) !std.ArrayList([2]f64) {
    var points = std.ArrayList([2]f64).init(allocator);
    for (0..steps + 1) |i| {
        const t = @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(steps));
        try points.append(.{
            r0 + (r1 - r0) * t,
            theta0 + (theta1 - theta0) * t,
        });
    }
    return points;
}

/// 螺旋路径：从起点出发，每步径向走 dr，周向走 dtheta
pub fn spiralPath(
    allocator: std.mem.Allocator,
    r0: f64, theta0: f64,
    steps: u32,
    dr: f64, dtheta: f64,
) !std.ArrayList([2]f64) {
    var points = std.ArrayList([2]f64).init(allocator);
    var r = r0;
    var theta = theta0;
    try points.append(.{ r, theta });
    for (0..steps) |_| {
        r += dr;
        theta += dtheta;
        try points.append(.{ r, theta });
    }
    return points;
}

