## `src/geometry.zig`（完整文件）

```zig
const std = @import("std");

pub const Vec3 = struct {
    x: f64, y: f64, z: f64,

    pub fn add(a: Vec3, b: Vec3) Vec3 { return .{ .x=a.x+b.x, .y=a.y+b.y, .z=a.z+b.z }; }
    pub fn sub(a: Vec3, b: Vec3) Vec3 { return .{ .x=a.x-b.x, .y=a.y-b.y, .z=a.z-b.z }; }
    pub fn scale(a: Vec3, s: f64) Vec3 { return .{ .x=a.x*s, .y=a.y*s, .z=a.z*s }; }
    pub fn dot(a: Vec3, b: Vec3) f64 { return a.x*b.x + a.y*b.y + a.z*b.z; }
    pub fn cross(a: Vec3, b: Vec3) Vec3 {
        return .{ .x = a.y*b.z - a.z*b.y, .y = a.z*b.x - a.x*b.z, .z = a.x*b.y - a.y*b.x };
    }
    pub fn len(a: Vec3) f64 { return @sqrt(a.dot(a)); }
    pub fn norm(a: Vec3) Vec3 {
        const l = a.len();
        if (l == 0) return a;
        return a.scale(1.0/l);
    }
};

pub const Face = struct { a: usize, b: usize, c: usize };

pub const Mesh = struct {
    verts: std.ArrayList(Vec3),
    faces: std.ArrayList(Face),
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) Mesh {
        return .{
            .verts = std.ArrayList(Vec3).init(allocator),
            .faces = std.ArrayList(Face).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Mesh) void {
        self.verts.deinit();
        self.faces.deinit();
    }

    pub fn centroid(self: *Mesh) Vec3 {
        var sum = Vec3{ .x=0, .y=0, .z=0 };
        for (self.verts.items) |v| sum = sum.add(v);
        const n = @as(f64, @floatFromInt(self.verts.items.len));
        return sum.scale(1.0/n);
    }

    pub fn faceCentroid(self: *Mesh, f: Face) Vec3 {
        const a = self.verts.items[f.a];
        const b = self.verts.items[f.b];
        const c = self.verts.items[f.c];
        return a.add(b).add(c).scale(1.0/3.0);
    }

    pub fn faceNormal(self: *Mesh, f: Face) Vec3 {
        const a = self.verts.items[f.a];
        const b = self.verts.items[f.b];
        const c = self.verts.items[f.c];
        return b.sub(a).cross(c.sub(a)).norm();
    }

    pub fn faceArea(self: *Mesh, f: Face) f64 {
        const a = self.verts.items[f.a];
        const b = self.verts.items[f.b];
        const c = self.verts.items[f.c];
        return b.sub(a).cross(c.sub(a)).len() * 0.5;
    }

    pub fn totalArea(self: *Mesh) f64 {
        var s: f64 = 0;
        for (self.faces.items) |f| s += self.faceArea(f);
        return s;
    }
};

/// 对称类型
pub const SymmetryType = enum {
    mirror_x, mirror_y, mirror_z,
    rot_z_90, rot_z_180,
};

/// 应用对称变换
pub fn applySymmetry(v: Vec3, t: SymmetryType, c: Vec3) Vec3 {
    const l = v.sub(c);
    const r: Vec3 = switch (t) {
        .mirror_x => .{ .x=-l.x, .y=l.y, .z=l.z },
        .mirror_y => .{ .x=l.x, .y=-l.y, .z=l.z },
        .mirror_z => .{ .x=l.x, .y=l.y, .z=-l.z },
        .rot_z_90 => .{ .x=-l.y, .y=l.x, .z=l.z },
        .rot_z_180 => .{ .x=-l.x, .y=-l.y, .z=l.z },
    };
    return r.add(c);
}

/// 验证一个对称变换：所有顶点映射后都还在顶点集里
pub fn verifySymmetry(mesh: *Mesh, t: SymmetryType, c: Vec3, tol: f64) bool {
    for (mesh.verts.items) |v| {
        const tv = applySymmetry(v, t, c);
        var found = false;
        for (mesh.verts.items) |u| {
            const d = tv.sub(u);
            if (d.dot(d) < tol * tol) { found = true; break; }
        }
        if (!found) return false;
    }
    return true;
}

/// 检测所有对称
pub fn detectSymmetries(mesh: *Mesh, allocator: std.mem.Allocator) !std.ArrayList(SymmetryType) {
    var result = std.ArrayList(SymmetryType).init(allocator);
    const c = mesh.centroid();
    const candidates = [_]SymmetryType{
        .mirror_x, .mirror_y, .mirror_z, .rot_z_90, .rot_z_180,
    };
    for (candidates) |t| {
        if (verifySymmetry(mesh, t, c, 1e-4)) try result.append(t);
    }
    return result;
}

/// 面级对称：每个面的对称伙伴
pub const FaceSymmetry = struct {
    face_idx: usize,
    partner: ?usize,
    sym_type: SymmetryType,
};

pub fn findFacePartners(
    mesh: *Mesh,
    t: SymmetryType,
    allocator: std.mem.Allocator,
) !std.ArrayList(FaceSymmetry) {
    var result = std.ArrayList(FaceSymmetry).init(allocator);
    const c = mesh.centroid();
    for (mesh.faces.items, 0..) |f, i| {
        const fc = mesh.faceCentroid(f);
        const tfc = applySymmetry(fc, t, c);
        var partner: ?usize = null;
        for (mesh.faces.items, 0..) |g, j| {
            if (i == j) continue;
            const d = tfc.sub(mesh.faceCentroid(g));
            if (d.dot(d) < 1e-6) { partner = j; break; }
        }
        try result.append(.{ .face_idx = i, .partner = partner, .sym_type = t });
    }
    return result;
}

/// 对偶多面体
pub const Dual = struct {
    verts: std.ArrayList(Vec3),
    faces: std.ArrayList(Face),
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator) Dual {
        return .{
            .verts = std.ArrayList(Vec3).init(allocator),
            .faces = std.ArrayList(Face).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Dual) void {
        self.verts.deinit();
        self.faces.deinit();
    }
};

pub fn buildDual(mesh: *Mesh, allocator: std.mem.Allocator) !Dual {
    var dual = Dual.init(allocator);
    for (mesh.faces.items) |f| {
        try dual.verts.append(mesh.faceCentroid(f));
    }
    for (mesh.verts.items, 0..) |_, vi| {
        var adj = std.ArrayList(usize).init(allocator);
        defer adj.deinit();
        for (mesh.faces.items, 0..) |f, fi| {
            if (f.a == vi or f.b == vi or f.c == vi) try adj.append(fi);
        }
        if (adj.items.len >= 3) {
            try dual.faces.append(.{
                .a = adj.items[0],
                .b = adj.items[1],
                .c = adj.items[2],
            });
        }
    }
    return dual;
}

/// 旋转体：一条线绕 z 轴旋转 N 圈，每圈一个停顿点，可加随机抖动
pub fn generateRotationalBody(
    allocator: std.mem.Allocator,
    base_radius: f64,
    turns: u32,
    samples_per_turn: u32,
    pause_jitter: f64,
    seed: u64,
) !std.ArrayList(Vec3) {
    var points = std.ArrayList(Vec3).init(allocator);
    var prng = std.Random.DefaultPrng.init(seed);
    const rand = prng.random();

    const total = turns * samples_per_turn;
    for (0..total) |i| {
        const t = @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(samples_per_turn));
        const theta = t * 2.0 * std.math.pi;

        var r = base_radius;
        if (i % samples_per_turn == 0) {
            r += (rand.float(f64) - 0.5) * 2.0 * pause_jitter;
        }

        try points.append(.{
            .x = r * @cos(theta),
            .y = r * @sin(theta),
            .z = t,
        });
    }
    return points;
}

