## `src/snapshot.zig`（完整文件）

```zig
const std = @import("std");
const pool_mod = @import("pool.zig");
const address_mod = @import("address.zig");
const index_mod = @import("index.zig");

const SlotPool = pool_mod.SlotPool;
const MyValue = address_mod.MyValue;
const AddressTable = address_mod.AddressTable;
const AddressSlot = address_mod.AddressSlot;
const InvertedIndex = index_mod.InvertedIndex;

/// 快照格式：只存逻辑状态，不存原始内存指针
pub const Snapshot = struct {
    version: u32 = 1,
    // 地址列表：地址 + 绑定槽索引 + 状态
    addresses: []AddressRecord,
    // 槽内容：槽索引 + 内容字节
    slots: []SlotRecord,
    // 倒排索引：关键词 → 地址列表
    keywords: []KeywordRecord,
};

pub const AddressRecord = struct {
    high: u64,
    low: u64,
    container: u16,
    pool_idx: ?usize,
    state: []const u8, // "unbound" / "bound" / "released"
};

pub const SlotRecord = struct {
    idx: usize,
    content: []const u8,
};

pub const KeywordRecord = struct {
    keyword: []const u8,
    addresses: []MyValue,
};

fn stateToString(s: @TypeOf(@as(AddressSlot, undefined).state)) []const u8 {
    return switch (s) {
        .unbound => "unbound",
        .bound => "bound",
        .released => "released",
    };
}

fn stateFromString(s: []const u8) @TypeOf(@as(AddressSlot, undefined).state) {
    if (std.mem.eql(u8, s, "bound")) return .bound;
    if (std.mem.eql(u8, s, "released")) return .released;
    return .unbound;
}

/// 从运行时导出快照
pub fn exportSnapshot(
    allocator: std.mem.Allocator,
    pool: *SlotPool,
    addresses: *AddressTable,
    inverted: *InvertedIndex,
) !Snapshot {
    // 地址记录
    var addr_records = std.ArrayList(AddressRecord).init(allocator);
    var it = addresses.map.iterator();
    while (it.next()) |entry| {
        const slot = entry.value_ptr.*;
        try addr_records.append(.{
            .high = entry.key_ptr.high,
            .low = entry.key_ptr.low,
            .container = entry.key_ptr.container,
            .pool_idx = slot.pool_idx,
            .state = stateToString(slot.state),
        });
    }

    // 槽内容记录：只存已绑定的槽
    var slot_records = std.ArrayList(SlotRecord).init(allocator);
    var addr_it = addresses.map.iterator();
    while (addr_it.next()) |entry| {
        const slot = entry.value_ptr.*;
        if (slot.pool_idx) |idx| {
            const buf = try pool.slot(idx);
            // 找到第一个 0，截断内容
            const end = std.mem.indexOfScalar(u8, buf, 0) orelse buf.len;
            try slot_records.append(.{
                .idx = idx,
                .content = try allocator.dupe(u8, buf[0..end]),
            });
        }
    }

    // 关键词记录
    var kw_records = std.ArrayList(KeywordRecord).init(allocator);
    var kw_it = inverted.map.iterator();
    while (kw_it.next()) |entry| {
        try kw_records.append(.{
            .keyword = try allocator.dupe(u8, entry.key_ptr.*),
            .addresses = try allocator.dupe(MyValue, entry.value_ptr.items),
        });
    }

    return .{
        .addresses = try addr_records.toOwnedSlice(),
        .slots = try slot_records.toOwnedSlice(),
        .keywords = try kw_records.toOwnedSlice(),
    };
}

/// 保存到文件（先写临时文件，再 rename）
pub fn save(
    allocator: std.mem.Allocator,
    pool: *SlotPool,
    addresses: *AddressTable,
    inverted: *InvertedIndex,
    path: []const u8,
) !void {
    const snap = try exportSnapshot(allocator, pool, addresses, inverted);

    const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{path});
    defer allocator.free(tmp_path);

    var file = try std.fs.cwd().createFile(tmp_path, .{});
    defer file.close();
    try std.json.stringify(snap, .{}, file.writer());
    try std.fs.cwd().rename(tmp_path, path);
}

/// 从文件加载，恢复到运行时
pub fn load(
    allocator: std.mem.Allocator,
    pool: *SlotPool,
    addresses: *AddressTable,
    inverted: *InvertedIndex,
    path: []const u8,
) !void {
    var file = std.fs.cwd().openFile(path, .{}) catch |err| {
        if (err == error.FileNotFound) return; // 首次运行，没快照
        return err;
    };
    defer file.close();

    const content = try file.readToEndAlloc(allocator, 10 * 1024 * 1024);
    defer allocator.free(content);

    const parsed = try std.json.parseFromSlice(Snapshot, allocator, content, .{
        .ignore_unknown_fields = true,
    });
    defer parsed.deinit();

    // 恢复地址
    for (parsed.value.addresses) |ar| {
        const addr = MyValue{ .high = ar.high, .low = ar.low, .container = ar.container };
        var slot = AddressSlot.init(addr);
        slot.pool_idx = ar.pool_idx;
        slot.state = stateFromString(ar.state);
        try addresses.map.put(addr, slot);
    }

    // 恢复槽内容
    for (parsed.value.slots) |sr| {
        const buf = try pool.slot(sr.idx);
        @memset(buf, 0);
        const n = @min(sr.content.len, buf.len);
        @memcpy(buf[0..n], sr.content[0..n]);
        // 从 free_list 移除这个槽
        var i: usize = 0;
        while (i < pool.free_list.items.len) {
            if (pool.free_list.items[i] == sr.idx) {
                _ = pool.free_list.orderedRemove(i);
            } else {
                i += 1;
            }
        }
    }

    // 恢复倒排索引
    for (parsed.value.keywords) |kr| {
        const gop = try inverted.map.getOrPut(kr.keyword);
        if (!gop.found_existing) {
            gop.value_ptr.* = std.ArrayList(MyValue).init(allocator);
        }
        for (kr.addresses) |addr| {
            try gop.value_ptr.append(addr);
        }
    }
}

// 测试：保存后加载，内容一致
test "snapshot save/load" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var pool = try SlotPool.init(allocator, 4, 64);
    defer pool.deinit();

    var table = AddressTable.init(allocator);
    defer table.deinit();

    var inv = InvertedIndex.init(allocator);
    defer inv.deinit();

    // 存两个地址，绑槽，写内容，建索引
    const a = MyValue{ .high = 1, .low = 0, .container = 1 };
    const b = MyValue{ .high = 2, .low = 0, .container = 1 };
    try table.register(a);
    try table.register(b);
    const idx_a = try table.bind(a, &pool);
    const idx_b = try table.bind(b, &pool);

    const buf_a = try pool.slot(idx_a);
    @memcpy(buf_a[0..11], "hello world");
    const buf_b = try pool.slot(idx_b);
    @memcpy(buf_b[0..13], "goodbye world");

    try inv.add("hello", a);
    try inv.add("world", a);
    try inv.add("goodbye", b);
    try inv.add("world", b);

    // 保存
    try save(allocator, &pool, &table, &inv, "test_snapshot.json");

    // 清空，重新加载
    table.map.clearRetainingCapacity();
    inv.deinit();
    inv = InvertedIndex.init(allocator);
    // 重置池
    pool.free_list.clearRetainingCapacity();
    for (0..4) |i| try pool.free_list.append(i);
    @memset(pool.block, 0);

    try load(allocator, &pool, &table, &inv, "test_snapshot.json");

    // 验证
    const loaded_a = table.lookup(a).?;
    try std.testing.expect(loaded_a.isBound());
    const loaded_buf = try pool.slot(loaded_a.pool_idx.?);
    try std.testing.expectEqualStrings("hello world", loaded_buf[0..11]);

    const world_addrs = inv.lookup("world").?;
    try std.testing.expect(world_addrs.len == 2);

    // 清理
    std.fs.cwd().deleteFile("test_snapshot.json") catch {};
}
