    // ========== 6. 磁悬浮仿真 ==========
    std.debug.print("\n=== 磁悬浮仿真 ===\n", .{});
    var params = control_mod.MaglevParams{};
    params.总时间 = 0.1;
    const result = try control_mod.simulateMaglev(allocator, params);
    std.debug.print("  最终间隙={d:.4}, 最终速度={d:.4}, 失稳={}, 最大电流={d:.3}\n",
        .{ result.最终间隙, result.最终速度, result.失稳, result.最大电流 });

    // ========== 7. 几何：正四面体 ==========
    std.debug.print("\n=== 几何：正四面体 ===\n", .{});
    var mesh = geometry_mod.Mesh.init(allocator);
    defer mesh.deinit();
    try mesh.verts.append(.{ .x = 1, .y = 1, .z = 1 });
    try mesh.verts.append(.{ .x = -1, .y = -1, .z = 1 });
    try mesh.verts.append(.{ .x = -1, .y = 1, .z = -1 });
