```zig
const std = @import("std");

/// 义项：一个汉字/词的一个含义
pub const Sense = struct {
    id: u32,
    gloss: []const u8,               // 义项解释
    category: u32,                   // 语义范畴
    keywords: []const []const u8,    // 触发这个词的关键词
    weight: f64,                     // 基础权重
};

/// 语义节点：字/词 + 多个义项
pub const SemNode = struct {
    id: u64,
    hanzi: []const u8,
    node_type: NodeType,
    senses: []const Sense,
    active_sense: ?u32,
};

pub const NodeType = enum {
    adjective, noun, verb, adverb, particle, compound,
};

/// 语境：周边词、当前范畴、最近激活节点
pub const Context = struct {
    nearby_words: []const []const u8,
    current_category: ?u32,
    recent_nodes: []const u64,
};

/// 消歧结果
pub const Disambiguation = struct {
    sense_id: ?u32,
    score: f64,
    reason: []const u8,
};

/// 消歧：根据语境给每个义项打分，选最高
pub fn disambiguate(
    node: SemNode,
    ctx: Context,
    edge_strength_fn: *const fn (recent: u64, node: u64, cat: u32) f64,
) Disambiguation {
    if (node.senses.len == 0) return .{ .sense_id = null, .score = 0, .reason = "无义项" };
    if (node.senses.len == 1) return .{ .sense_id = node.senses[0].id, .score = node.senses[0].weight, .reason = "唯一义项" };

    var best_id: ?u32 = null;
    var best_score: f64 = -1e9;

    for (node.senses) |s| {
        var score: f64 = s.weight;

        // 1. 范畴匹配
        if (ctx.current_category) |cat| {
            if (s.category == cat) score += 2.0;
        }

        // 2. 关键词匹配
        for (ctx.nearby_words) |w| {
            for (s.keywords) |kw| {
                if (std.mem.eql(u8, w, kw)) score += 1.5;
            }
        }

        // 3. 最近激活节点关联
        for (ctx.recent_nodes) |rid| {
            score += edge_strength_fn(rid, node.id, s.category);
        }

        if (score > best_score) {
            best_score = score;
            best_id = s.id;
        }
    }

    return .{ .sense_id = best_id, .score = best_score, .reason = "语境打分" };
}

/// 组合规则：左类型 + 右类型 → 结果类型
pub const CombineRule = struct {
    left: NodeType,
    right: NodeType,
    result: NodeType,
    name: []const u8,
    strength_fn: enum { min, avg, product },
};

pub const RULES = [_]CombineRule{
    .{ .left = .adjective, .right = .noun, .result = .compound, .name = "偏正", .strength_fn = .min },
    .{ .left = .verb, .right = .noun, .result = .compound, .name = "动宾", .strength_fn = .avg },
    .{ .left = .noun, .right = .noun, .result = .compound, .name = "并列/所属", .strength_fn = .min },
    .{ .left = .adverb, .right = .verb, .result = .compound, .name = "状中", .strength_fn = .min },
    .{ .left = .adverb, .right = .adjective, .result = .compound, .name = "状中", .strength_fn = .min },
};

/// 组合结果
pub const CombineResult = struct {
    success: bool,
    new_hanzi: ?[]const u8,
    rule_name: []const u8,
    strength: f64,
    reason: []const u8,
    left_sense: ?u32,
    right_sense: ?u32,
};

fn categoryCompatible(a: u32, b: u32) bool {
    return a == b or a == 0 or b == 0;
}

/// 组合：先消歧，再查规则，再检查范畴兼容
pub fn combine(
    allocator: std.mem.Allocator,
    a: SemNode,
    b: SemNode,
    ctx: Context,
    edge_strength_ab: f64,
    edge_strength_fn: *const fn (recent: u64, node: u64, cat: u32) f64,
) !CombineResult {
    // 1. 消歧
    const da = disambiguate(a, ctx, edge_strength_fn);
    const db = disambiguate(b, ctx, edge_strength_fn);

    if (da.sense_id == null or db.sense_id == null) {
        return .{ .success = false, .new_hanzi = null, .rule_name = "",
                  .strength = 0, .reason = "义项无法确定",
                  .left_sense = da.sense_id, .right_sense = db.sense_id };
    }

    const sense_a = findSense(a, da.sense_id.?);
    const sense_b = findSense(b, db.sense_id.?);

    // 2. 查规则
    for (RULES) |r| {
        if (r.left == a.node_type and r.right == b.node_type) {
            // 3. 范畴兼容检查
            if (!categoryCompatible(sense_a.category, sense_b.category)) {
                continue;
            }

            const new_hanzi = try std.fmt.allocPrint(allocator, "{s}{s}", .{ a.hanzi, b.hanzi });

            const s = switch (r.strength_fn) {
                .min => @min(edge_strength_ab, 1.0),
                .avg => edge_strength_ab * 0.5 + 0.5,
                .product => edge_strength_ab * edge_strength_ab,
            };

            return .{
                .success = true,
                .new_hanzi = new_hanzi,
                .rule_name = r.name,
                .strength = s * sense_a.weight * sense_b.weight,
                .reason = "消歧后规则匹配",
                .left_sense = da.sense_id,
                .right_sense = db.sense_id,
            };
        }
    }

    return .{ .success = false, .new_hanzi = null, .rule_name = "",
              .strength = 0, .reason = "消歧后无匹配规则",
              .left_sense = da.sense_id, .right_sense = db.sense_id };
}

fn findSense(node: SemNode, sense_id: u32) Sense {
    for (node.senses) |s| {
        if (s.id == sense_id) return s;
    }
    return node.senses[0];
}

// ========== 测试 ==========

fn mockEdgeStrength(_: u64, _: u64, _: u32) f64 {
    return 0.0;
}

test "disambiguate color vs business" {
    const hong = SemNode{
        .id = 1, .hanzi = "红", .node_type = .adjective, .active_sense = null,
        .senses = &.{
            .{ .id = 0, .gloss = "颜色红", .category = 1, .keywords = &.{ "玫瑰", "太阳" }, .weight = 1.0 },
            .{ .id = 1, .gloss = "红火", .category = 2, .keywords = &.{ "生意", "市场" }, .weight = 0.8 },
        },
    };

    // 语境：玫瑰 / 植物
    const ctx1 = Context{ .nearby_words = &.{ "玫瑰" }, .current_category = 1, .recent_nodes = &.{} };
    const d1 = disambiguate(hong, ctx1, mockEdgeStrength);
    try std.testing.expect(d1.sense_id.? == 0);

    // 语境：生意 / 经济
    const ctx2 = Context{ .nearby_words = &.{ "生意" }, .current_category = 2, .recent_nodes = &.{} };
    const d2 = disambiguate(hong, ctx2, mockEdgeStrength);
    try std.testing.expect(d2.sense_id.? == 1);
}

test "combine red + flower" {
    const hong = SemNode{
        .id = 1, .hanzi = "红", .node_type = .adjective, .active_sense = null,
        .senses = &.{
            .{ .id = 0, .gloss = "颜色红", .category = 1, .keywords = &.{ "玫瑰" }, .weight = 1.0 },
        },
    };
    const hua = SemNode{
        .id = 2, .hanzi = "花", .node_type = .noun, .active_sense = null,
        .senses = &.{
            .{ .id = 0, .gloss = "花朵", .category = 1, .keywords = &.{ "玫瑰" }, .weight = 1.0 },
        },
    };

    const ctx = Context{ .nearby_words = &.{ "玫瑰" }, .current_category = 1, .recent_nodes = &.{} };
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const r = try combine(allocator, hong, hua, ctx, 0.8, mockEdgeStrength);
    defer if (r.new_hanzi) |h| allocator.free(h);

    try std.testing.expect(r.success);
    try std.testing.expectEqualStrings("红花", r.new_hanzi.?);
    try std.testing.expectEqualStrings("偏正", r.rule_name);
}

test "combine noun + verb rejected" {
    const hua = SemNode{
        .id = 2, .hanzi = "花", .node_type = .noun, .active_sense = null,
        .senses = &.{
            .{ .id = 0, .gloss = "花朵", .category = 1, .keywords = &.{}, .weight = 1.0 },
        },
    };
    const chi = SemNode{
        .id = 3, .hanzi = "吃", .node_type = .verb, .active_sense = null,
        .senses = &.{
            .{ .id = 0, .gloss = "吃", .category = 2, .keywords = &.{}, .weight = 1.0 },
        },
    };

    const ctx = Context{ .nearby_words = &.{}, .current_category = null, .recent_nodes = &.{} };
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const r = try combine(allocator, hua, chi, ctx, 0.5, mockEdgeStrength);
    try std.testing.expect(!r.success);
    try std.testing.expectEqualStrings("消歧后无匹配规则", r.reason);
}
