const std = @import("std");
const semantic = @import("semantic.zig");

const SemNode = semantic.SemNode;
const Sense = semantic.Sense;
const Context = semantic.Context;
const CombineResult = semantic.CombineResult;
const combine = semantic.combine;
const disambiguate = semantic.disambiguate;
const NodeType = semantic.NodeType;

/// 生成意图：想表达什么
pub const Intent = struct {
    goal: []const u8,           // 意图名，如"描述红花"
    target_category: ?u32,      // 目标语义范畴
    slots: []const IntentSlot,  // 待填槽位
    desired_order: []const u8,  // 期望顺序，如"形名" / "动宾"
};

pub const IntentSlot = struct {
    name: []const u8,           // 槽位名，如"修饰语""中心词"
    allowed_types: []const NodeType, // 允许的节点类型
    candidate_ids: []const u64, // 候选节点 id
};

/// 生成的步骤记录
pub const Step = struct {
    slot_name: []const u8,
    chosen_id: u64,
    chosen_hanzi: []const u8,
    chosen_sense: ?u32,
    score: f64,
};

/// 生成结果
pub const GenerateResult = struct {
    success: bool,
    output: ?[]const u8,        // 最终输出
    steps: []Step,              // 每步选了什么
    reason: []const u8,
};

/// 从候选节点里，按语境和槽位类型选一个
fn selectForSlot(
    allocator: std.mem.Allocator,
    slot: IntentSlot,
    nodes: []const SemNode,
    ctx: Context,
    edge_strength_fn: *const fn (u64, u64, u32) f64,
) !?Step {
    _ = allocator;
    var best: ?Step = null;
    var best_score: f64 = -1e9;

    for (slot.candidate_ids) |cid| {
        // 找节点
        var node: ?SemNode = null;
        for (nodes) |n| {
            if (n.id == cid) { node = n; break; }
        }
        if (node == null) continue;

        // 类型检查
        var type_ok = false;
        for (slot.allowed_types) |t| {
            if (node.?.node_type == t) { type_ok = true; break; }
        }
        if (!type_ok) continue;

        // 消歧
        const d = disambiguate(node.?, ctx, edge_strength_fn);
        if (d.sense_id == null) continue;

        if (d.score > best_score) {
            best_score = d.score;
            best = Step{
                .slot_name = slot.name,
                .chosen_id = node.?.id,
                .chosen_hanzi = node.?.hanzi,
                .chosen_sense = d.sense_id,
                .score = d.score,
            };
        }
    }
    return best;
}

/// 组合后的义项继承：
/// - 如果左右义项同范畴，新节点继承该范畴
/// - 如果不同范畴，新节点继承左侧范畴（偏正结构中心在左）
/// - 权重 = 左右权重乘积
fn inheritSense(
    allocator: std.mem.Allocator,
    left: SemNode,
    right: SemNode,
    left_sense_id: u32,
    right_sense_id: u32,
) !Sense {
    var left_sense: ?Sense = null;
    var right_sense: ?Sense = null;
    for (left.senses) |s| if (s.id == left_sense_id) { left_sense = s; break; };
    for (right.senses) |s| if (s.id == right_sense_id) { right_sense = s; break; };

    const ls = left_sense orelse left.senses[0];
    const rs = right_sense orelse right.senses[0];

    const cat = if (ls.category == rs.category) ls.category else ls.category;
    const gloss = try std.fmt.allocPrint(allocator, "{s}+{s}", .{ ls.gloss, rs.gloss });

    return Sense{
        .id = 0,
        .gloss = gloss,
        .category = cat,
        .keywords = &.{},
        .weight = ls.weight * rs.weight,
    };
}

/// 从意图生成：按槽位选词、按顺序组合、继承义项
pub fn generate(
    allocator: std.mem.Allocator,
    intent: Intent,
    nodes: []const SemNode,
    ctx: Context,
    edge_strength_fn: *const fn (u64, u64, u32) f64,
) !GenerateResult {
    var steps = std.ArrayList(Step).init(allocator);
    var chosen_nodes = std.ArrayList(SemNode).init(allocator);
    defer chosen_nodes.deinit();

    // 1. 按槽位选词
    for (intent.slots) |slot| {
        const step = try selectForSlot(allocator, slot, nodes, ctx, edge_strength_fn);
        if (step == null) {
            return .{
                .success = false, .output = null,
                .steps = try steps.toOwnedSlice(),
                .reason = "槽位无候选",
            };
        }
        try steps.append(step.?);

        // 收集选中节点
        for (nodes) |n| {
            if (n.id == step.?.chosen_id) {
                try chosen_nodes.append(n);
                break;
            }
        }
    }

    // 2. 按顺序组合
    if (chosen_nodes.items.len == 0) {
        return .{ .success = false, .output = null,
                  .steps = try steps.toOwnedSlice(), .reason = "无选中节点" };
    }

    var current = chosen_nodes.items[0];
    for (chosen_nodes.items[1..]) |next| {
        const r = try combine(allocator, current, next, ctx, 1.0, edge_strength_fn);
        if (!r.success) {
            return .{
                .success = false, .output = null,
                .steps = try steps.toOwnedSlice(),
                .reason = r.reason,
            };
        }

        // 继承义项
        const inherited = try inheritSense(
            allocator, current, next,
            r.left_sense orelse 0, r.right_sense orelse 0,
        );

        current = SemNode{
            .id = 0,
            .hanzi = r.new_hanzi.?,
            .node_type = .compound,
            .senses = try allocator.dupe(Sense, &.{inherited}),
            .active_sense = inherited.id,
        };
    }

    return .{
        .success = true,
        .output = current.hanzi,
        .steps = try steps.toOwnedSlice(),
        .reason = "生成完成",
    };
}

