const std = @import("std");

/// 关系等级：从高到低
pub const RelationLevel = enum {
    trusted,     // 信任：维护分 >= 80
    stable,      // 稳定：维护分 >= 50
    fragile,     // 脆弱：维护分 >= 20
    broken,      // 断裂：维护分 < 20

    pub fn fromScore(score: f64) RelationLevel {
        if (score >= 80) return .trusted;
        if (score >= 50) return .stable;
        if (score >= 20) return .fragile;
        return .broken;
    }
};

/// 关系：公共资源，需要持续维护，不是私有储蓄
pub const Relation = struct {
    id: u64,
    from: u64,           // 主体 A
    to: u64,             // 主体 B
    kind: []const u8,    // 关系类型："同事""朋友""合作"
    maintenance: f64,    // 维护分 0~100
    last_maintain: f64,  // 最后维护时间
    total_withdraw: f64, // 累计支取量
    total_deposit: f64,  // 累计维护量

    pub fn level(self: Relation) RelationLevel {
        return RelationLevel.fromScore(self.maintenance);
    }

    /// 支取：使用关系获得支持，扣维护分
    /// 扣多少 = base_cost × (1 + 累计支取 / 累计维护)
    /// 支取越多、维护越少，扣得越狠
    pub fn withdraw(self: *Relation, amount: f64, now: f64) struct {
        success: bool,
        new_maintenance: f64,
        cost: f64,
        reason: []const u8,
    } {
        if (self.level() == .broken) {
            return .{ .success = false, .new_maintenance = self.maintenance,
                      .cost = 0, .reason = "关系已断裂，无法支取" };
        }

        // 成本随支取/维护比上升
        const ratio = if (self.total_deposit > 0)
            self.total_withdraw / self.total_deposit
        else
            10.0; // 从未维护过，成本极高
        const cost = amount * (1.0 + ratio);

        if (self.maintenance < cost) {
            // 维护分不够，关系降级
            const before = self.level();
            self.maintenance = 0;
            self.total_withdraw += amount;
            const after = self.level();
            return .{
                .success = false,
                .new_maintenance = 0,
                .cost = cost,
                .reason = if (before != after) "支取失败，关系降级" else "支取失败，维护分不足",
            };
        }

        self.maintenance -= cost;
        self.total_withdraw += amount;
        self.last_maintain = now;

        return .{ .success = true, .new_maintenance = self.maintenance,
                  .cost = cost, .reason = "支取成功" };
    }

    /// 维护：投入时间/资源，恢复维护分
    /// 恢复量 = amount × (1 - maintenance/100)
    /// 维护分越高，恢复越难（边际递减）
    pub fn maintain(self: *Relation, amount: f64, now: f64) f64 {
        const room = 1.0 - self.maintenance / 100.0;
        const gain = amount * room;
        self.maintenance = @min(100.0, self.maintenance + gain);
        self.total_deposit += amount;
        self.last_maintain = now;
        return gain;
    }

    /// 自然衰减：时间越久不维护，维护分越低
    /// decay = rate × elapsed_days
    pub fn decay(self: *Relation, now: f64, rate_per_day: f64) void {
        const elapsed_days = (now - self.last_maintain) / 86400.0;
        if (elapsed_days <= 0) return;
        const decay = rate_per_day * elapsed_days;
        self.maintenance = @max(0.0, self.maintenance - decay);
    }
};

/// 关系表
pub const RelationTable = struct {
    relations: std.AutoHashMap(u64, Relation),
    allocator: std.mem.Allocator,
    next_id: u64,

    pub fn init(allocator: std.mem.Allocator) RelationTable {
        return .{
            .relations = std.AutoHashMap(u64, Relation).init(allocator),
            .allocator = allocator,
            .next_id = 1,
        };
    }

    pub fn deinit(self: *RelationTable) void {
        self.relations.deinit();
    }

    pub fn create(self: *RelationTable, from: u64, to: u64, kind: []const u8) !u64 {
        const id = self.next_id;
        self.next_id += 1;
        try self.relations.put(id, .{
            .id = id, .from = from, .to = to, .kind = kind,
            .maintenance = 50.0, // 初始维护分 50，稳定但不高
            .last_maintain = 0, .total_withdraw = 0, .total_deposit = 0,
        });
        return id;
    }

    pub fn get(self: *RelationTable, id: u64) ?*Relation {
        return self.relations.getPtr(id);
    }

    /// 全局衰减：所有关系按时间衰减
    pub fn decayAll(self: *RelationTable, now: f64, rate_per_day: f64) void {
        var it = self.relations.valueIterator();
        while (it.next()) |r| r.decay(now, rate_per_day);
    }

    /// 统计：各等级关系数量
    pub fn levelCounts(self: *RelationTable) [4]usize {
        var counts = [4]usize{ 0, 0, 0, 0 };
        var it = self.relations.valueIterator();
        while (it.next()) |r| {
            counts[@intFromEnum(r.level())] += 1;
        }
        return counts;
    }
};

// ========== 测试 ==========

test "withdraw reduces maintenance" {
    var table = RelationTable.init(std.testing.allocator);
    defer table.deinit();

    const rid = try table.create(1, 2, "朋友");
    const r = table.get(rid).?;

    // 初始 50，支取 10
    const result = r.withdraw(10, 0);
    try std.testing.expect(result.success);
    try std.testing.expect(result.new_maintenance < 50.0);
    try std.testing.expect(result.cost > 10.0); // 有支取/维护比加成
}

test "withdraw fails when broken" {
    var table = RelationTable.init(std.testing.allocator);
    defer table.deinit();

    const rid = try table.create(1, 2, "同事");
    const r = table.get(rid).?;
    r.maintenance = 10.0; // 脆弱

    // 支取超过维护分
    const result = r.withdraw(100, 0);
    try std.testing.expect(!result.success);
    try std.testing.expect(r.level() == .broken);
}

test "maintain with diminishing returns" {
    var table = RelationTable.init(std.testing.allocator);
    defer table.deinit();

    const rid = try table.create(1, 2, "合作");
    const r = table.get(rid).?;
    r.maintenance = 80.0;

    // 维护 10，但只剩 20% 空间，实际增益约 2
    const gain = r.maintain(10, 0);
    try std.testing.expect(gain < 10.0);
    try std.testing.expect(r.maintenance > 80.0);
}

test "decay over time" {
    var table = RelationTable.init(std.testing.allocator);
    defer table.deinit();

    const rid = try table.create(1, 2, "朋友");
    const r = table.get(rid).?;
    r.maintenance = 50.0;
    r.last_maintain = 0;

    // 10 天后，每天衰减 2，共衰减 20
    r.decay(10 * 86400.0, 2.0);
    try std.testing.expectApproxEqAbs(r.maintenance, 30.0, 1e-9);
}

test "level counts" {
    var table = RelationTable.init(std.testing.allocator);
    defer table.deinit();

    const r1 = try table.create(1, 2, "a");
    table.get(r1).?.maintenance = 90; // trusted
    const r2 = try table.create(1, 3, "b");
    table.get(r2).?.maintenance = 60; // stable
    const r3 = try table.create(1, 4, "c");
    table.get(r3).?.maintenance = 30; // fragile
    const r4 = try table.create(1, 5, "d");
    table.get(r4).?.maintenance = 5;  // broken

    const counts = table.levelCounts();
    try std.testing.expect(counts[0] == 1); // trusted
    try std.testing.expect(counts[1] == 1); // stable
    try std.testing.expect(counts[2] == 1); // fragile
    try std.testing.expect(counts[3] == 1); // broken
}
