```zig
const std = @import("std");
const relation_mod = @import("relation.zig");
const Relation = relation_mod.Relation;
const RelationLevel = relation_mod.RelationLevel;

/// 间接支取结果
pub const IndirectWithdraw = struct {
    success: bool,
    total_cost: f64,
    path: []const u64,      // 经过的关系 id 路径
    hops: usize,
    reason: []const u8,
};

/// 声誉传播结果
pub const ReputationPropagation = struct {
    affected: []const u64,  // 受影响的关系 id
    total_decay: f64,       // 总衰减量
};

/// 关系网络：多对多关系图
pub const RelationNet = struct {
    relations: std.AutoHashMap(u64, Relation),
    outgoing: std.AutoHashMap(u64, std.ArrayList(u64)),
    allocator: std.mem.Allocator,
    next_id: u64,

    pub fn init(allocator: std.mem.Allocator) RelationNet {
        return .{
            .relations = std.AutoHashMap(u64, Relation).init(allocator),
            .outgoing = std.AutoHashMap(u64, std.ArrayList(u64)).init(allocator),
            .allocator = allocator,
            .next_id = 1,
        };
    }

    pub fn deinit(self: *RelationNet) void {
        self.relations.deinit();
        var it = self.outgoing.valueIterator();
        while (it.next()) |list| list.deinit();
        self.outgoing.deinit();
    }

    /// 创建关系，更新邻接表
    pub fn create(self: *RelationNet, from: u64, to: u64, kind: []const u8) !u64 {
        const id = self.next_id;
        self.next_id += 1;
        try self.relations.put(id, .{
            .id = id, .from = from, .to = to, .kind = kind,
            .maintenance = 50.0, .last_maintain = 0,
            .total_withdraw = 0, .total_deposit = 0,
        });
        const gop = try self.outgoing.getOrPut(from);
        if (!gop.found_existing) {
            gop.value_ptr.* = std.ArrayList(u64).init(self.allocator);
        }
        try gop.value_ptr.append(id);
        return id;
    }

    pub fn get(self: *RelationNet, id: u64) ?*Relation {
        return self.relations.getPtr(id);
    }

    /// 直接支取：单条关系支取
    pub fn directWithdraw(self: *RelationNet, id: u64, amount: f64, now: f64) !struct {
        success: bool, cost: f64, reason: []const u8,
    } {
        const r = self.get(id) orelse return .{ .success = false, .cost = 0, .reason = "关系不存在" };
        const w = r.withdraw(amount, now);
        return .{ .success = w.success, .cost = w.cost, .reason = w.reason };
    }

    /// 间接支取：A 通过中间人 B 向 C 支取
    /// 传递规则：每经过一条关系，成本乘以 1.5（传递损耗）
    /// 只走 maintenance >= 50（stable 及以上）的关系
    pub fn indirectWithdraw(
        self: *RelationNet,
        from: u64,
        to: u64,
        amount: f64,
        now: f64,
        max_hops: usize,
    ) !IndirectWithdraw {
        // BFS 找路径
        var visited = std.AutoHashMap(u64, void).init(self.allocator);
        defer visited.deinit();

        const PathNode = struct {
            node: u64,
            path: []const u64,
            cost_multiplier: f64,
        };

        var queue = std.ArrayList(PathNode).init(self.allocator);
        defer queue.deinit();

        // 起始路径：空路径
        try queue.append(.{ .node = from, .path = &.{}, .cost_multiplier = 1.0 });
        try visited.put(from, {});

        while (queue.items.len > 0) {
            const cur = queue.orderedRemove(0);

            if (cur.node == to and cur.path.len > 0) {
                // 找到路径，计算总成本
                var total_cost: f64 = 0;
                for (cur.path) |rid| {
                    const r = self.get(rid) orelse continue;
                    // 每条关系的支取成本
                    const ratio = if (r.total_deposit > 0)
                        r.total_withdraw / r.total_deposit
                    else
                        10.0;
                    const edge_cost = amount * (1.0 + ratio);
                    total_cost += edge_cost * cur.cost_multiplier;

                    // 实际支取：扣维护分
                    if (r.maintenance < edge_cost * cur.cost_multiplier) {
                        return .{
                            .success = false, .total_cost = total_cost,
                            .path = cur.path, .hops = cur.path.len,
                            .reason = "中间关系维护分不足",
                        };
                    }
                    r.maintenance -= edge_cost * cur.cost_multiplier;
                    r.total_withdraw += amount;
                }
                return .{
                    .success = true, .total_cost = total_cost,
                    .path = cur.path, .hops = cur.path.len,
                    .reason = "间接支取成功",
                };
            }

            if (cur.path.len >= max_hops) continue;

            // 扩展：走 outgoing 关系
            if (self.outgoing.get(cur.node)) |edges| {
                for (edges.items) |rid| {
                    const r = self.get(rid) orelse continue;
                    // 只走 stable 及以上的关系
                    if (@intFromEnum(r.level()) > @intFromEnum(RelationLevel.stable)) continue;
                    if (visited.contains(r.to)) continue;

                    try visited.put(r.to, {});
                    var new_path = try self.allocator.alloc(u64, cur.path.len + 1);
                    @memcpy(new_path[0..cur.path.len], cur.path);
                    new_path[cur.path.len] = rid;

                    try queue.append(.{
                        .node = r.to,
                        .path = new_path,
                        .cost_multiplier = cur.cost_multiplier * 1.5, // 传递损耗
                    });
                }
            }
        }

        return .{
            .success = false, .total_cost = 0,
            .path = &.{}, .hops = 0,
            .reason = "无可用路径",
        };
    }

    /// 声誉传播：一条关系断裂，影响相邻关系的维护分
    /// 断裂关系影响的相邻关系：所有 from 或 to 相同的其他关系
    /// 传播衰减：每跳乘以 0.5
    pub fn propagateReputation(
        self: *RelationNet,
        broken_id: u64,
        decay_per_neighbor: f64,
    ) !ReputationPropagation {
        const broken = self.get(broken_id) orelse return .{
            .affected = &.{}, .total_decay = 0,
        };

        var affected = std.ArrayList(u64).init(self.allocator);
        var total_decay: f64 = 0;

        // 找相邻关系：from 或 to 匹配断裂关系的任一端
        var it = self.relations.iterator();
        while (it.next()) |entry| {
            const rid = entry.key_ptr.*;
            if (rid == broken_id) continue;
            const r = entry.value_ptr;

            if (r.from == broken.from or r.from == broken.to
                or r.to == broken.from or r.to == broken.to) {
                r.maintenance = @max(0.0, r.maintenance - decay_per_neighbor);
                try affected.append(rid);
                total_decay += decay_per_neighbor;
            }
        }

        return .{
            .affected = try affected.toOwnedSlice(),
            .total_decay = total_decay,
        };
    }

    /// 查某节点的所有关系
    pub fn relationsOf(self: *RelationNet, node: u64, allocator: std.mem.Allocator) !std.ArrayList(Relation) {
        var result = std.ArrayList(Relation).init(allocator);
        var it = self.relations.valueIterator();
        while (it.next()) |r| {
            if (r.from == node or r.to == node) {
                try result.append(r.*);
            }
        }
        return result;
    }
};

