const std = @import("std");

/// 相位槽：每个相位一个槽
pub const PhaseSlot = struct {
    phase: f64,        // 相位值
    revealed: bool,    // 是否已释放
    activation: f64,   // 观测强度（吸引子强度）
    position: [3]f64,  // 隐藏时的位置（不显示）
    id: u64,           // 槽 id
};

/// 相位表：管理所有相位的隐藏/释放
pub const PhaseTable = struct {
    slots: std.ArrayList(PhaseSlot),
    allocator: std.mem.Allocator,
    reveal_count: usize,  // 已释放数量

    pub fn init(allocator: std.mem.Allocator, count: usize) !PhaseTable {
        var slots = std.ArrayList(PhaseSlot).init(allocator);
        for (0..count) |i| {
            const phase = 2.0 * std.math.pi * @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(count));
            try slots.append(.{
                .id = i,
                .phase = phase,
                .revealed = false,
                .activation = 0.0,
                .position = .{ 0, 0, 0 },
            });
        }
        return .{ .slots = slots, .allocator = allocator, .reveal_count = 0 };
    }

    pub fn deinit(self: *PhaseTable) void {
        self.slots.deinit();
    }

    /// 眼睛观测：给某个方向的相位加强度，用 cos(delta) 加权减差
    pub fn observe(self: *PhaseTable, observed_phase: f64, strength: f64) void {
        for (self.slots.items) |*s| {
            const delta = s.phase - observed_phase;
            s.activation += strength * @cos(delta);
            // 强度不能为负
            if (s.activation < 0) s.activation = 0;
        }
    }

    /// 释放一个相位：选强度最高且未释放的
    pub fn releaseOne(self: *PhaseTable) ?f64 {
        var best_idx: ?usize = null;
        var best_act: f64 = -1e9;
        for (self.slots.items, 0..) |s, i| {
            if (s.revealed) continue;
            if (s.activation > best_act) {
                best_act = s.activation;
                best_idx = i;
            }
        }
        if (best_idx) |idx| {
            self.slots.items[idx].revealed = true;
            self.slots.items[idx].activation = 0.0;
            self.reveal_count += 1;
            return self.slots.items[idx].phase;
        }
        return null;
    }

    /// 相位轮换：所有相位加 delta
    pub fn rotateAll(self: *PhaseTable, delta: f64) void {
        for (self.slots.items) |*s| {
            s.phase += delta;
        }
    }

    /// 全息共轭：所有相位取反
    pub fn conjugateAll(self: *PhaseTable) void {
        for (self.slots.items) |*s| {
            s.phase = -s.phase;
        }
    }

    /// 重置：所有相位隐藏
    pub fn reset(self: *PhaseTable) void {
        for (self.slots.items) |*s| {
            s.revealed = false;
            s.activation = 0.0;
        }
        self.reveal_count = 0;
    }

    /// 全息投影：计算所有相位的合成强度
    pub fn hologramStrength(self: *PhaseTable) f64 {
        var total: f64 = 0;
        for (self.slots.items) |s| {
            total += s.activation * @cos(s.phase);
        }
        return total;
    }

    /// 干涉：两个相位的合成强度
    pub fn interfere(phase_a: f64, act_a: f64, phase_b: f64, act_b: f64) f64 {
        const delta = phase_a - phase_b;
        return act_a + act_b + 2.0 * @sqrt(@max(0, act_a * act_b)) * @cos(delta);
    }
};

/// 角度公差：点积 + 弦长阈值，无三角函数
pub fn angleWithinTolerance(a: [3]f64, b: [3]f64, tol_rad: f64) bool {
    const dot = a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
    const cos_tol = @cos(tol_rad);
    const chord_sq = 2.0 * (1.0 - dot);
    const tol_chord_sq = 2.0 * (1.0 - cos_tol);
    return chord_sq <= tol_chord_sq;
}

/// n 重对称下的角度公差：先取模再比较
pub fn angleWithinToleranceMod(a: [3]f64, b: [3]f64, tol_rad: f64, n: u32) bool {
    const phase_a = std.math.atan2(a[1], a[0]);
    const phase_b = std.math.atan2(b[1], b[0]);
    const two_pi_over_n = 2.0 * std.math.pi / @as(f64, @floatFromInt(n));
    const diff = @mod(phase_a - phase_b + two_pi_over_n / 2.0, two_pi_over_n) - two_pi_over_n / 2.0;
    return @abs(diff) <= tol_rad;
}
