        self.slots.deinit();
    }

    /// 眼睛观测：给某个方向的相位加强度，用 cos(delta) 加权减差
    /// 同相增强，反相削弱
    pub fn observe(self: *PhaseTable, observed_phase: f64, strength: f64) void {
        for (self.slots.items) |*s| {
            const delta = s.phase - observed_phase;
            s.activation += strength * @cos(delta);
            if (s.activation < 0) s.activation = 0;
        }
    }

    /// 释放一个相位：选强度最高且未释放的
    /// 一次只释放一个
    pub fn releaseOne(self: *PhaseTable) ?f64 {
        var best_idx: ?usize = null;
        var best_act: f64 = -1e9;
        for (self.slots.items, 0..) |s, i| {
            if (s.revealed) continue;
            if (s.activation > best_act) {
                best_act = s.activation;
                best_idx = i;
            }
        }
        if (best_idx) |idx| {
            self.slots.items[idx].revealed = true;
            self.slots.items[idx].activation = 0.0;
            self.reveal_count += 1;
            return self.slots.items[idx].phase;
        }
        return null;
    }

    /// 相位轮换：所有相位加 delta
    pub fn rotateAll(self: *PhaseTable, delta: f64) void {
        for (self.slots.items) |*s| {
            s.phase += delta;
        }
    }

    /// 全息共轭：所有相位取反
    pub fn conjugateAll(self: *PhaseTable) void {
        for (self.slots.items) |*s| {
            s.phase = -s.phase;
        }
    }

    /// 重置：所有相位隐藏
    pub fn reset(self: *PhaseTable) void {
        for (self.slots.items) |*s| {
            s.revealed = false;
            s.activation = 0.0;
        }
        self.reveal_count = 0;
    }

    /// 全息投影：所有相位的合成强度
    pub fn hologramStrength(self: *PhaseTable) f64 {
        var total: f64 = 0;
        for (self.slots.items) |s| {
            total += s.activation * @cos(s.phase);
        }
        return total;
    }

    /// 干涉：两个相位的合成强度（离散干涉）
    pub fn interfere(phase_a: f64, act_a: f64, phase_b: f64, act_b: f64) f64 {
        const delta = phase_a - phase_b;
        return act_a + act_b + 2.0 * @sqrt(@max(0, act_a * act_b)) * @cos(delta);
    }
};

/// 角度公差：点积 + 弦长阈值，无三角函数（除 cos(tol) 一次）
/// a、b 必须是单位向量
pub fn angleWithinTolerance(a: [3]f64, b: [3]f64, tol_rad: f64) bool {
    const dot = a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
    const cos_tol = @cos(tol_rad);
    const chord_sq = 2.0 * (1.0 - dot);
    const tol_chord_sq = 2.0 * (1.0 - cos_tol);
    return chord_sq <= tol_chord_sq;
}

/// n 重对称下的角度公差：先取模到 [0, 2π/n) 再比较
pub fn angleWithinToleranceMod(a: [3]f64, b: [3]f64, tol_rad: f64, n: u32) bool {
    const phase_a = std.math.atan2(a[1], a[0]);
    const phase_b = std.math.atan2(b[1], b[0]);
    const two_pi_over_n = 2.0 * std.math.pi / @as(f64, @floatFromInt(n));
    const diff = @mod(phase_a - phase_b + two_pi_over_n / 2.0, two_pi_over_n) - two_pi_over_n / 2.0;
    return @abs(diff) <= tol_rad;
}

// ========== 测试 ==========

test "observe strengthens nearby phase" {
    var table = try PhaseTable.init(std.testing.allocator, 4);
    defer table.deinit();

    // 相位 0, π/2, π, 3π/2
    table.observe(0.0, 1.0);

    // 相位 0 的 activation 应该最高（cos(0)=1）
    // 相位 π 的应该最低（cos(π)=-1，被削到 0）
    try std.testing.expect(table.slots.items[0].activation > 0.9);
    try std.testing.expect(table.slots.items[2].activation < 0.1);
    try std.testing.expect(table.slots.items[1].activation > 0.0); // π/2，cos=0
}

test "release one picks highest" {
    var table = try PhaseTable.init(std.testing.allocator, 4);
    defer table.deinit();

    table.observe(0.0, 1.0);
    const phase = table.releaseOne().?;
    try std.testing.expectApproxEqAbs(phase, 0.0, 1e-9);
    try std.testing.expect(table.reveal_count == 1);

    // 再释放一个，应该是 π/2 或 3π/2（cos=0，activation 相同）
    const phase2 = table.releaseOne().?;
    try std.testing.expect(phase2 != phase);
    try std.testing.expect(table.reveal_count == 2);
}

test "release all phases" {
    var table = try PhaseTable.init(std.testing.allocator, 4);
    defer table.deinit();

    // 每个方向都观测一次，让所有相位有 activation
    table.observe(0.0, 1.0);
    table.observe(std.math.pi / 2.0, 1.0);
    table.observe(std.math.pi, 1.0);
    table.observe(3.0 * std.math.pi / 2.0, 1.0);

    var count: usize = 0;
    while (table.releaseOne()) |_| count += 1;
    try std.testing.expect(count == 4);
    try std.testing.expect(table.reveal_count == 4);

    // 再释放返回 null
    try std.testing.expect(table.releaseOne() == null);
}

test "interfere constructively and destructively" {
    // 同相：增强
    const c1 = PhaseTable.interfere(0.0, 1.0, 0.0, 1.0);
    try std.testing.expectApproxEqAbs(c1, 4.0, 1e-9); // 1+1+2·1·1

    // 反相：抵消
    const c2 = PhaseTable.interfere(0.0, 1.0, std.math.pi, 1.0);
    try std.testing.expectApproxEqAbs(c2, 0.0, 1e-9); // 1+1-2
}

test "angle tolerance" {
    const a = [_]f64{ 1, 0, 0 };
    const b = [_]f64{ 0.99, 0.1, 0 };
    const len_b = @sqrt(0.99*0.99 + 0.1*0.1);
    const b_norm = [_]f64{ 0.99/len_b, 0.1/len_b, 0 };

    // 夹角约 5.7°，容差 0.2 rad（约 11.5°）
    try std.testing.expect(angleWithinTolerance(&a, &b_norm, 0.2));

    // 垂直向量，容差 0.2 rad，不通过
    const c = [_]f64{ 0, 1, 0 };
    try std.testing.expect(!angleWithinTolerance(&a, &c, 0.2));
}

test "angle tolerance mod n" {
    const a = [_]f64{ 1, 0, 0 };
    // 旋转 120°，3 重对称下应该和 0° 等价
    const angle_120 = 2.0 * std.math.pi / 3.0;
    const b = [_]f64{ @cos(angle_120), @sin(angle_120), 0 };

    // 3 重对称，容差 0.01 rad
    try std.testing.expect(angleWithinToleranceMod(&a, &b, 0.01, 3));

    // 2 重对称，120° 不等价
    try std.testing.expect(!angleWithinToleranceMod(&a, &b, 0.01, 2));
}
