## `src/intent.zig`（完整文件）

```zig
const std = @import("std");
const phase_mod = @import("phase.zig");
const PhaseTable = phase_mod.PhaseTable;

pub const Vec3 = struct {
    x: f64, y: f64, z: f64,
    pub fn add(a: Vec3, b: Vec3) Vec3 { return .{ .x=a.x+b.x, .y=a.y+b.y, .z=a.z+b.z }; }
    pub fn sub(a: Vec3, b: Vec3) Vec3 { return .{ .x=a.x-b.x, .y=a.y-b.y, .z=a.z-b.z }; }
    pub fn scale(a: Vec3, s: f64) Vec3 { return .{ .x=a.x*s, .y=a.y*s, .z=a.z*s }; }
    pub fn dot(a: Vec3, b: Vec3) f64 { return a.x*b.x + a.y*b.y + a.z*b.z; }
    pub fn len(a: Vec3) f64 { return @sqrt(a.dot(a)); }
};

/// 意图锚点：目标位置 + 目标相位 + 强度
pub const IntentAnchor = struct {
    position: Vec3,
    phase: f64,
    strength: f64,   // 锚点强度 0~1
};

/// 意图状态
pub const IntentState = struct {
    position: Vec3,
    phase: f64,
    velocity: Vec3,
    potential: f64,  // 当前势能
};

/// 算子类型
pub const OperatorKind = enum {
    frequency,   // 频率算子：调相位速度
    relation,    // 关系算子：调关系权重（影响势能）
    potential,   // 势能算子：调势能
    time,        // 时间算子：调速度衰减
    spatial,     // 空间轨迹算子：调位置
};

pub const Operator = struct {
    kind: OperatorKind,
    weight: f64,
    param: f64,
};

/// 释放判定结果
pub const ReleaseVerdict = enum {
    released,        // 释放相位
    held,            // 维持，继续冲击
    boundary_switched, // 到边界，调换相位
    no_strength,     // 强度不够
};

/// 吸引子力：拉向锚点
pub fn attractorForce(state: IntentState, anchor: IntentAnchor, k: f64) Vec3 {
    const d = anchor.position.sub(state.position);
    const dist = d.len();
    if (dist < 1e-6) return .{ .x=0, .y=0, .z=0 };
    const mag = @min(k * anchor.strength / (dist + 0.1), anchor.strength);
    return d.scale(1.0 / dist * mag);
}

/// 应用一个算子
pub fn applyOperator(state: *IntentState, op: Operator) void {
    switch (op.kind) {
        .frequency => state.phase += op.param * op.weight,
        .potential => state.potential += op.param * op.weight,
        .spatial => {
            state.position.x += op.param * op.weight;
            state.position.y += op.param * op.weight;
        },
        .time => {
            state.velocity.x *= (1.0 + op.param * op.weight);
            state.velocity.y *= (1.0 + op.param * op.weight);
        },
        .relation => state.potential -= op.param * op.weight,
    }
}

/// 相位释放判定
pub fn tryRelease(
    state: IntentState,
    anchor: IntentAnchor,
    strength_threshold: f64,
    boundary_eps: f64,
) ReleaseVerdict {
    // 强度不够
    if (anchor.strength < strength_threshold) return .no_strength;

    const phase_diff = @abs(state.phase - anchor.phase);

    // 到了边界：释放
    if (phase_diff <= boundary_eps) return .released;

    // 还没到：继续冲击
    if (phase_diff > boundary_eps * 3.0) return .held;

    // 接近边界但未到：调换相位
    return .boundary_switched;
}

/// 意图流运行结果
pub const IntentFlowResult = struct {
    final_position: Vec3,
    final_phase: f64,
    final_potential: f64,
    steps: u32,
    released: bool,
    release_step: ?u32,
    verdict: ReleaseVerdict,
};

/// 运行意图流：吸引子 + 算子 + 相位释放
pub fn runIntentFlow(
    allocator: std.mem.Allocator,
    anchor: IntentAnchor,
    initial: IntentState,
    ops: []const Operator,
    max_steps: u32,
    strength_threshold: f64,
    boundary_eps: f64,
) !IntentFlowResult {
    _ = allocator;
    var state = initial;
    var step: u32 = 0;
    var released = false;
    var release_step: ?u32 = null;

    while (step < max_steps) : (step += 1) {
        // 1. 吸引子拉
        const force = attractorForce(state, anchor, 1.0);
        state.velocity = state.velocity.add(force);
        state.position = state.position.add(state.velocity);

        // 2. 应用算子
        for (ops) |op| applyOperator(&state, op);

        // 3. 相位释放判定
        const v = tryRelease(state, anchor, strength_threshold, boundary_eps);
        if (v == .released) {
            released = true;
            release_step = step;
            state.phase = anchor.phase;
            break;
        }

        // 4. 势能衰减：防止无限累积
        state.potential *= 0.99;
        if (state.potential < 0) state.potential = 0;
    }

    return .{
        .final_position = state.position,
        .final_phase = state.phase,
        .final_potential = state.potential,
        .steps = step,
        .released = released,
        .release_step = release_step,
        .verdict = tryRelease(state, anchor, strength_threshold, boundary_eps),
    };
}

/// 意图流驱动相位表：释放一个相位
pub fn flowDrivesPhase(
    phase_table: *PhaseTable,
    anchor: IntentAnchor,
    state: IntentState,
    strength_threshold: f64,
    boundary_eps: f64,
) ?f64 {
    // 眼睛观测：用锚点强度做观测
    phase_table.observe(anchor.phase, anchor.strength);

    // 判定是否可以释放
    const v = tryRelease(state, anchor, strength_threshold, boundary_eps);
    if (v == .released) {
        return phase_table.releaseOne();
    }
    return null;
}

// ========== 测试 ==========

test "attractor pulls toward anchor" {
    const state = IntentState{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .velocity = .{ .x=0, .y=0, .z=0 },
        .potential = 1.0,
    };
    const anchor = IntentAnchor{
        .position = .{ .x=5, .y=5, .z=0 },
        .phase = 0.0,
        .strength = 1.0,
    };
    const f = attractorForce(state, anchor, 1.0);
    try std.testing.expect(f.x > 0);
    try std.testing.expect(f.y > 0);
}

test "operator changes phase" {
    var state = IntentState{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .velocity = .{ .x=0, .y=0, .z=0 },
        .potential = 1.0,
    };
    const op = Operator{ .kind = .frequency, .weight = 1.0, .param = 0.1 };
    applyOperator(&state, op);
    try std.testing.expectApproxEqAbs(state.phase, 0.1, 1e-9);
}

test "release when phase matches" {
    const state = IntentState{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 3.14,
        .velocity = .{ .x=0, .y=0, .z=0 },
        .potential = 1.0,
    };
    const anchor = IntentAnchor{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 3.14,
        .strength = 1.0,
    };
    try std.testing.expect(tryRelease(state, anchor, 0.5, 0.1) == .released);
}

test "no strength when threshold not met" {
    const state = IntentState{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .velocity = .{ .x=0, .y=0, .z=0 },
        .potential = 1.0,
    };
    const anchor = IntentAnchor{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .strength = 0.3,
    };
    try std.testing.expect(tryRelease(state, anchor, 0.5, 0.1) == .no_strength);
}

test "intent flow reaches anchor" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const anchor = IntentAnchor{
        .position = .{ .x=1, .y=1, .z=0 },
        .phase = 1.0,
        .strength = 0.9,
    };
    const initial = IntentState{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .velocity = .{ .x=0, .y=0, .z=0 },
        .potential = 1.0,
    };
    const ops = [_]Operator{
        .{ .kind = .frequency, .weight = 1.0, .param = 0.05 },
    };

    const result = try runIntentFlow(
        allocator, anchor, initial, &ops, 200, 0.5, 0.05,
    );
    try std.testing.expect(result.released);
    try std.testing.expect(result.release_step != null);
}

test "flow drives phase table" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var phase_table = try PhaseTable.init(allocator, 4);
    defer phase_table.deinit();

    const anchor = IntentAnchor{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .strength = 1.0,
    };
    const state = IntentState{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .velocity = .{ .x=0, .y=0, .z=0 },
        .potential = 1.0,
    };

    const released_phase = flowDrivesPhase(&phase_table, anchor, state, 0.5, 0.1);
    try std.testing.expect(released_phase != null);
    try std.testing.expectApproxEqAbs(released_phase.?, 0.0, 1e-9);
}
