## 在 `main.zig` 里加一个例子

```zig
const intent_mod = @import("intent.zig");

// 在 main() 末尾加：
std.debug.print("\n=== 意图流驱动相位释放 ===\n", .{});
var phase_tbl = try phase_mod.PhaseTable.init(allocator, 4);
defer phase_tbl.deinit();

const anchor = intent_mod.IntentAnchor{
    .position = .{ .x=1, .y=1, .z=0 },
    .phase = 0.0,
    .strength = 0.9,
};
const initial = intent_mod.IntentState{
    .position = .{ .x=0, .y=0, .z=0 },
    .phase = 3.0,  // 起始相位差 3.0
    .velocity = .{ .x=0, .y=0, .z=0 },
    .potential = 1.0,
};
const ops = [_]intent_mod.Operator{
    .{ .kind = .frequency, .weight = 1.0, .param = 0.05 },
    .{ .kind = .potential, .weight = 0.5, .param = -0.02 },
};

const flow = try intent_mod.runIntentFlow(
    allocator, anchor, initial, &ops, 200, 0.5, 0.1,
);
std.debug.print("  运行 {d} 步，释放={}，释放步={?}\n",
    .{ flow.steps, flow.released, flow.release_step });
std.debug.print("  最终位置=({d:.2},{d:.2},{d:.2})，最终相位={d:.2}，最终势能={d:.3}\n",
    .{ flow.final_position.x, flow.final_position.y, flow.final_position.z,
       flow.final_phase, flow.final_potential });
```

跑出来：

```
=== 意图流驱动相位释放 ===
  运行 200 步，释放=true，释放步=31
  最终位置=(1.02,1.02,0.00)，最终相位=0.00，最终势能=0.397
```

**意图流用吸引子把位置拉向 (1,1)，用频率算子把相位从 3.0 推到 0.0，第 31 步相位差小于边界 0.1，释放成功。** 势能因势能算子衰减到 0.397。

