## `src/snapshot.zig`（扩展版，完整文件）

```zig
const std = @import("std");
const pool_mod = @import("pool.zig");
const address_mod = @import("address.zig");
const index_mod = @import("index.zig");
const relation_mod = @import("relation.zig");
const relation_net_mod = @import("relation_net.zig");
const phase_mod = @import("phase.zig");

const SlotPool = pool_mod.SlotPool;
const MyValue = address_mod.MyValue;
const AddressTable = address_mod.AddressTable;
const AddressSlot = address_mod.AddressSlot;
const InvertedIndex = index_mod.InvertedIndex;
const Relation = relation_mod.Relation;
const RelationNet = relation_net_mod.RelationNet;
const PhaseSlot = phase_mod.PhaseSlot;
const PhaseTable = phase_mod.PhaseTable;

pub const Snapshot = struct {
    version: u32 = 2,
    addresses: []AddressRecord,
    slots: []SlotRecord,
    keywords: []KeywordRecord,
    relations: []RelationRecord,
    phases: []PhaseRecord,
};

pub const AddressRecord = struct {
    high: u64, low: u64, container: u16,
    pool_idx: ?usize, state: []const u8,
};

pub const SlotRecord = struct { idx: usize, content: []const u8 };

pub const KeywordRecord = struct {
    keyword: []const u8,
    addresses: []MyValue,
};

pub const RelationRecord = struct {
    id: u64, from: u64, to: u64,
    kind: []const u8,
    maintenance: f64, last_maintain: f64,
    total_withdraw: f64, total_deposit: f64,
};

pub const PhaseRecord = struct {
    id: u64, phase: f64, revealed: bool,
    activation: f64,
    position: [3]f64,
};

fn stateToString(s: @TypeOf(@as(AddressSlot, undefined).state)) []const u8 {
    return switch (s) {
        .unbound => "unbound", .bound => "bound", .released => "released",
    };
}
fn stateFromString(s: []const u8) @TypeOf(@as(AddressSlot, undefined).state) {
    if (std.mem.eql(u8, s, "bound")) return .bound;
    if (std.mem.eql(u8, s, "released")) return .released;
    return .unbound;
}

pub fn exportSnapshot(
    allocator: std.mem.Allocator,
    pool: *SlotPool,
    addresses: *AddressTable,
    inverted: *InvertedIndex,
    net: *RelationNet,
    phase_table: *PhaseTable,
) !Snapshot {
    // 地址
    var addr_records = std.ArrayList(AddressRecord).init(allocator);
    var it = addresses.map.iterator();
    while (it.next()) |entry| {
        const slot = entry.value_ptr.*;
        try addr_records.append(.{
            .high = entry.key_ptr.high, .low = entry.key_ptr.low,
            .container = entry.key_ptr.container,
            .pool_idx = slot.pool_idx, .state = stateToString(slot.state),
        });
    }

    // 槽
    var slot_records = std.ArrayList(SlotRecord).init(allocator);
    var sit = addresses.map.iterator();
    while (sit.next()) |entry| {
        const slot = entry.value_ptr.*;
        if (slot.pool_idx) |idx| {
            const buf = try pool.slot(idx);
            const end = std.mem.indexOfScalar(u8, buf, 0) orelse buf.len;
            try slot_records.append(.{ .idx = idx, .content = try allocator.dupe(u8, buf[0..end]) });
        }
    }

    // 关键词
    var kw_records = std.ArrayList(KeywordRecord).init(allocator);
    var kit = inverted.map.iterator();
    while (kit.next()) |entry| {
        try kw_records.append(.{
            .keyword = try allocator.dupe(u8, entry.key_ptr.*),
            .addresses = try allocator.dupe(MyValue, entry.value_ptr.items),
        });
    }

    // 关系
    var rel_records = std.ArrayList(RelationRecord).init(allocator);
    var rit = net.relations.valueIterator();
    while (rit.next()) |r| {
        try rel_records.append(.{
            .id = r.id, .from = r.from, .to = r.to,
            .kind = try allocator.dupe(u8, r.kind),
            .maintenance = r.maintenance, .last_maintain = r.last_maintain,
            .total_withdraw = r.total_withdraw, .total_deposit = r.total_deposit,
        });
    }

    // 相位
    var phase_records = std.ArrayList(PhaseRecord).init(allocator);
    for (phase_table.slots.items) |s| {
        try phase_records.append(.{
            .id = s.id, .phase = s.phase, .revealed = s.revealed,
            .activation = s.activation, .position = s.position,
        });
    }

    return .{
        .addresses = try addr_records.toOwnedSlice(),
        .slots = try slot_records.toOwnedSlice(),
        .keywords = try kw_records.toOwnedSlice(),
        .relations = try rel_records.toOwnedSlice(),
        .phases = try phase_records.toOwnedSlice(),
    };
}

pub fn save(
    allocator: std.mem.Allocator,
    pool: *SlotPool,
    addresses: *AddressTable,
    inverted: *InvertedIndex,
    net: *RelationNet,
    phase_table: *PhaseTable,
    path: []const u8,
) !void {
    const snap = try exportSnapshot(allocator, pool, addresses, inverted, net, phase_table);
    const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{path});
    defer allocator.free(tmp_path);

    var file = try std.fs.cwd().createFile(tmp_path, .{});
    defer file.close();
    try std.json.stringify(snap, .{}, file.writer());
    try std.fs.cwd().rename(tmp_path, path);
}

pub fn load(
    allocator: std.mem.Allocator,
    pool: *SlotPool,
    addresses: *AddressTable,
    inverted: *InvertedIndex,
    net: *RelationNet,
    phase_table: *PhaseTable,
    path: []const u8,
) !void {
    var file = std.fs.cwd().openFile(path, .{}) catch |err| {
        if (err == error.FileNotFound) return;
        return err;
    };
    defer file.close();

    const content = try file.readToEndAlloc(allocator, 10 * 1024 * 1024);
    defer allocator.free(content);

    const parsed = try std.json.parseFromSlice(Snapshot, allocator, content, .{
        .ignore_unknown_fields = true,
    });
    defer parsed.deinit();

    // 地址
    for (parsed.value.addresses) |ar| {
        const addr = MyValue{ .high = ar.high, .low = ar.low, .container = ar.container };
        var slot = AddressSlot.init(addr);
        slot.pool_idx = ar.pool_idx;
        slot.state = stateFromString(ar.state);
        try addresses.map.put(addr, slot);
    }

    // 槽
    for (parsed.value.slots) |sr| {
        const buf = try pool.slot(sr.idx);
        @memset(buf, 0);
        const n = @min(sr.content.len, buf.len);
        @memcpy(buf[0..n], sr.content[0..n]);
        var i: usize = 0;
        while (i < pool.free_list.items.len) {
            if (pool.free_list.items[i] == sr.idx) {
                _ = pool.free_list.orderedRemove(i);
            } else i += 1;
        }
    }

    // 关键词
    for (parsed.value.keywords) |kr| {
        const gop = try inverted.map.getOrPut(kr.keyword);
        if (!gop.found_existing) {
            gop.value_ptr.* = std.ArrayList(MyValue).init(allocator);
        }
        for (kr.addresses) |addr| try gop.value_ptr.append(addr);
    }

    // 关系
    for (parsed.value.relations) |rr| {
        const r = Relation{
            .id = rr.id, .from = rr.from, .to = rr.to, .kind = rr.kind,
            .maintenance = rr.maintenance, .last_maintain = rr.last_maintain,
            .total_withdraw = rr.total_withdraw, .total_deposit = rr.total_deposit,
        };
        try net.relations.put(rr.id, r);
        const gop = try net.outgoing.getOrPut(rr.from);
        if (!gop.found_existing) {
            gop.value_ptr.* = std.ArrayList(u64).init(allocator);
        }
        try gop.value_ptr.append(rr.id);
        if (rr.id >= net.next_id) net.next_id = rr.id + 1;
    }

    // 相位
    for (parsed.value.phases) |pr| {
        phase_table.slots.items[pr.id] = .{
            .id = pr.id, .phase = pr.phase, .revealed = pr.revealed,
            .activation = pr.activation, .position = pr.position,
        };
    }
    var revealed: usize = 0;
    for (phase_table.slots.items) |s| if (s.revealed) { revealed += 1; };
    phase_table.reveal_count = revealed;
}
```

