## `src/symmetry.zig`（完整文件）

```zig
const std = @import("std");

pub const Vec3 = struct {
    x: f64, y: f64, z: f64,
    pub fn add(a: Vec3, b: Vec3) Vec3 { return .{ .x=a.x+b.x, .y=a.y+b.y, .z=a.z+b.z }; }
    pub fn sub(a: Vec3, b: Vec3) Vec3 { return .{ .x=a.x-b.x, .y=a.y-b.y, .z=a.z-b.z }; }
    pub fn scale(a: Vec3, s: f64) Vec3 { return .{ .x=a.x*s, .y=a.y*s, .z=a.z*s }; }
    pub fn dot(a: Vec3, b: Vec3) f64 { return a.x*b.x + a.y*b.y + a.z*b.z; }
    pub fn len(a: Vec3) f64 { return @sqrt(a.dot(a)); }
    pub fn norm(a: Vec3) Vec3 { const l = a.len(); if (l == 0) return a; return a.scale(1.0/l); }
};

/// 群元素类型
pub const GroupKind = enum {
    identity,      // 恒等
    mirror_x,      // 关于 yz 平面镜像
    mirror_y,      // 关于 xz 平面镜像
    mirror_z,      // 关于 xy 平面镜像
    rot_z_90,      // 绕 z 轴 90°
    rot_z_180,     // 绕 z 轴 180°
    rot_z_270,     // 绕 z 轴 270°
    reflect_origin,// 点反射
};

/// 群元素：一个变换
pub const GroupElement = struct {
    kind: GroupKind,

    /// 应用变换到向量（关于原点）
    pub fn apply(self: GroupElement, v: Vec3) Vec3 {
        return switch (self.kind) {
            .identity => v,
            .mirror_x => .{ .x=-v.x, .y=v.y, .z=v.z },
            .mirror_y => .{ .x=v.x, .y=-v.y, .z=v.z },
            .mirror_z => .{ .x=v.x, .y=v.y, .z=-v.z },
            .rot_z_90 => .{ .x=-v.y, .y=v.x, .z=v.z },
            .rot_z_180 => .{ .x=-v.x, .y=-v.y, .z=v.z },
            .rot_z_270 => .{ .x=v.y, .y=-v.x, .z=v.z },
            .reflect_origin => .{ .x=-v.x, .y=-v.y, .z=-v.z },
        };
    }

    /// 应用变换到向量（关于中心 c）
    pub fn applyAround(self: GroupElement, v: Vec3, c: Vec3) Vec3 {
        return self.apply(v.sub(c)).add(c);
    }

    /// 逆元素
    pub fn inverse(self: GroupElement) GroupElement {
        return switch (self.kind) {
            .identity => .{ .kind = .identity },
            .mirror_x, .mirror_y, .mirror_z, .rot_z_180, .reflect_origin => self,
            .rot_z_90 => .{ .kind = .rot_z_270 },
            .rot_z_270 => .{ .kind = .rot_z_90 },
        };
    }

    /// 群乘法：先 self，再 other
    pub fn compose(self: GroupElement, other: GroupElement) GroupElement {
        // 简化：只处理对易的情况，非对易返回 identity 占位
        if (self.kind == .identity) return other;
        if (other.kind == .identity) return self;
        if (self.kind == other.kind) {
            // 自乘：mirror 两次 = identity，rot_90 两次 = rot_180
            return switch (self.kind) {
                .mirror_x, .mirror_y, .mirror_z => .{ .kind = .identity },
                .rot_z_90 => .{ .kind = .rot_z_180 },
                .rot_z_180 => .{ .kind = .identity },
                .rot_z_270 => .{ .kind = .rot_z_180 },
                .reflect_origin => .{ .kind = .identity },
                else => .{ .kind = .identity },
            };
        }
        return .{ .kind = .identity }; // 占位，非对易未实现
    }
};

/// 群作用：一组群元素作用于空间
pub const GroupAction = struct {
    elements: []const GroupElement,
    center: Vec3,

    /// 轨道：一个点在群作用下的所有像
    pub fn orbit(self: GroupAction, v: Vec3, allocator: std.mem.Allocator) !std.ArrayList(Vec3) {
        var result = std.ArrayList(Vec3).init(allocator);
        for (self.elements) |e| {
            try result.append(e.applyAround(v, self.center));
        }
        return result;
    }

    /// 不动点：群作用下不变的点
    pub fn fixedPoints(self: GroupAction, points: []const Vec3, tol: f64, allocator: std.mem.Allocator) !std.ArrayList(Vec3) {
        var result = std.ArrayList(Vec3).init(allocator);
        for (points) |p| {
            var is_fixed = true;
            for (self.elements) |e| {
                const tp = e.applyAround(p, self.center);
                const d = tp.sub(p);
                if (d.dot(d) > tol * tol) { is_fixed = false; break; }
            }
            if (is_fixed) try result.append(p);
        }
        return result;
    }
};

/// 镜像群：关于某轴的镜像
pub fn mirrorGroup(axis: enum { x, y, z }) GroupElement {
    return switch (axis) {
        .x => .{ .kind = .mirror_x },
        .y => .{ .kind = .mirror_y },
        .z => .{ .kind = .mirror_z },
    };
}

/// 循环群：n 重旋转
pub fn cyclicGroup(n: u32, allocator: std.mem.Allocator) !std.ArrayList(GroupElement) {
    var result = std.ArrayList(GroupElement).init(allocator);
    const step = 2.0 * std.math.pi / @as(f64, @floatFromInt(n));
    for (0..n) |i| {
        const angle = step * @as(f64, @floatFromInt(i));
        // 用四舍五入判断，避免浮点误差
        const rounded = @round(angle / (std.math.pi / 2.0));
        const kind: GroupKind = switch (@as(u32, @intCast(@mod(@as(i64, @intFromFloat(rounded)), 4)))) {
            0 => .identity,
            1 => .rot_z_90,
            2 => .rot_z_180,
            3 => .rot_z_270,
            else => .identity,
        };
        try result.append(.{ .kind = kind });
    }
    return result;
}

/// 群阶数：群元素数量
pub fn groupOrder(elements: []const GroupElement) usize {
    return elements.len;
}

/// 检查是否是阿贝尔群：所有元素对易
pub fn isAbelian(elements: []const GroupElement) bool {
    for (elements) |a| {
        for (elements) |b| {
            const ab = a.compose(b);
            const ba = b.compose(a);
            if (ab.kind != ba.kind) return false;
        }
    }
    return true;
}

/// 平衡算法：用镜像群检查左右平衡
/// 左右对称：v 和 mirror_x(v) 都在点集里
pub fn checkBalance(
    points: []const Vec3,
    center: Vec3,
    tol: f64,
) bool {
    const m = mirrorGroup(.x);
    for (points) |p| {
        const mp = m.applyAround(p, center);
        var found = false;
        for (points) |q| {
            const d = mp.sub(q);
            if (d.dot(d) < tol * tol) { found = true; break; }
        }
        if (!found) return false;
    }
    return true;
}

/// 对称群不变量：在群作用下不变的量
pub fn invariantSum(points: []const Vec3) f64 {
    var sum: f64 = 0;
    for (points) |p| sum += p.x + p.y + p.z;
    return sum;
}

/// 角度公差：点积 + 弦长（复用 phase.zig 的思路，但独立实现）
pub fn angleWithinTolerance(a: Vec3, b: Vec3, tol_rad: f64) bool {
    const an = a.norm();
    const bn = b.norm();
    const dot = an.dot(bn);
    const chord_sq = 2.0 * (1.0 - dot);
    const tol_chord_sq = 2.0 * (1.0 - @cos(tol_rad));
    return chord_sq <= tol_chord_sq;
}

/// n 重对称下的角度等价
pub fn angleEquivalentModN(phase_a: f64, phase_b: f64, tol: f64, n: u32) bool {
    const two_pi_over_n = 2.0 * std.math.pi / @as(f64, @floatFromInt(n));
    const diff = @mod(phase_a - phase_b + two_pi_over_n / 2.0, two_pi_over_n) - two_pi_over_n / 2.0;
    return @abs(diff) <= tol;
}

