## `src/runtime.zig`（完整文件）

```zig
const std = @import("std");

const pool_mod = @import("pool.zig");
const address_mod = @import("address.zig");
const index_mod = @import("index.zig");
const relation_net_mod = @import("relation_net.zig");
const phase_mod = @import("phase.zig");
const intent_mod = @import("intent.zig");
const symmetry_mod = @import("symmetry.zig");
const snapshot_mod = @import("snapshot.zig");

const SlotPool = pool_mod.SlotPool;
const MyValue = address_mod.MyValue;
const AddressTable = address_mod.AddressTable;
const ContentIndex = index_mod.ContentIndex;
const InvertedIndex = index_mod.InvertedIndex;
const indexContent = index_mod.indexContent;
const RelationNet = relation_net_mod.RelationNet;
const PhaseTable = phase_mod.PhaseTable;

/// 统一运行时：所有子系统在一个结构里
pub const Runtime = struct {
    allocator: std.mem.Allocator,
    pool: *SlotPool,
    addresses: *AddressTable,
    contents: ContentIndex,
    inverted: InvertedIndex,
    relations: RelationNet,
    phases: PhaseTable,
    next_id: u64,

    pub fn init(
        allocator: std.mem.Allocator,
        slot_count: usize,
        slot_size: usize,
        phase_count: usize,
    ) !Runtime {
        const pool = try allocator.create(SlotPool);
        pool.* = try SlotPool.init(allocator, slot_count, slot_size);

        const addresses = try allocator.create(AddressTable);
        addresses.* = AddressTable.init(allocator);

        return .{
            .allocator = allocator,
            .pool = pool,
            .addresses = addresses,
            .contents = ContentIndex.init(addresses, pool),
            .inverted = InvertedIndex.init(allocator),
            .relations = RelationNet.init(allocator),
            .phases = try PhaseTable.init(allocator, phase_count),
            .next_id = 1,
        };
    }

    pub fn deinit(self: *Runtime) void {
        self.phases.deinit();
        self.relations.deinit();
        self.inverted.deinit();
        self.addresses.deinit();
        self.allocator.destroy(self.addresses);
        self.pool.deinit();
        self.allocator.destroy(self.pool);
    }

    // ========== 高级入口 ==========

    /// 存内容：分配地址、绑定槽、写内容、建倒排索引
    pub fn store(self: *Runtime, content: []const u8) !MyValue {
        const addr = MyValue{ .high = self.next_id, .low = 0, .container = 1 };
        self.next_id += 1;

        try self.addresses.register(addr);
        const idx = try self.addresses.bind(addr, self.pool);
        const buf = try self.pool.slot(idx);
        @memset(buf, 0);
        try indexContent(self.allocator, &self.contents, &self.inverted, addr, content);
        return addr;
    }

    /// 召唤内容
    pub fn recall(self: *Runtime, addr: MyValue, out: []u8) !usize {
        return self.contents.get(addr, out);
    }

    /// 建关系
    pub fn link(self: *Runtime, from: u64, to: u64, kind: []const u8) !u64 {
        return self.relations.create(from, to, kind);
    }

    /// 意图驱动相位释放：给锚点，跑到释放或超步数
    pub fn driveIntent(
        self: *Runtime,
        anchor: intent_mod.IntentAnchor,
        initial: intent_mod.IntentState,
        ops: []const intent_mod.Operator,
        max_steps: u32,
        strength_threshold: f64,
        boundary_eps: f64,
    ) !?f64 {
        // 先观测相位表
        self.phases.observe(anchor.phase, anchor.strength);

        // 跑意图流
        const flow = try intent_mod.runIntentFlow(
            self.allocator, anchor, initial, ops, max_steps,
            strength_threshold, boundary_eps,
        );

        // 如果释放了，从相位表里释放一个
        if (flow.released) {
            return self.phases.releaseOne();
        }
        return null;
    }

    /// 平衡检查：用镜像群检查点集
    pub fn checkBalance(
        self: *Runtime,
        points: []const symmetry_mod.Vec3,
        center: symmetry_mod.Vec3,
        tol: f64,
    ) bool {
        _ = self;
        return symmetry_mod.checkBalance(points, center, tol);
    }

    /// 保存快照
    pub fn saveSnapshot(self: *Runtime, path: []const u8) !void {
        std.fs.cwd().makePath(std.fs.path.dirname(path) orelse ".") catch {};
        try snapshot_mod.save(
            self.allocator, self.pool, self.addresses,
            &self.inverted, &self.relations, &self.phases, path,
        );
    }

    /// 加载快照
    pub fn loadSnapshot(self: *Runtime, path: []const u8) !void {
        try snapshot_mod.load(
            self.allocator, self.pool, self.addresses,
            &self.inverted, &self.relations, &self.phases, path,
        );
    }
};

// ========== 测试 ==========

test "runtime store and recall" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var rt = try Runtime.init(allocator, 8, 64, 4);
    defer rt.deinit();

    const addr = try rt.store("hello runtime");
    var buf: [64]u8 = [_]u8{0} ** 64;
    const n = try rt.recall(addr, &buf);
    const actual = std.mem.indexOfScalar(u8, &buf, 0) orelse n;
    try std.testing.expectEqualStrings("hello runtime", buf[0..actual]);
}

test "runtime link relations" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var rt = try Runtime.init(allocator, 4, 64, 4);
    defer rt.deinit();

    _ = try rt.link(1, 2, "朋友");
    _ = try rt.link(2, 3, "同事");
    try std.testing.expect(rt.relations.relations.count() == 2);
}

test "runtime drive intent releases phase" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var rt = try Runtime.init(allocator, 4, 64, 4);
    defer rt.deinit();

    const anchor = intent_mod.IntentAnchor{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .strength = 1.0,
    };
    const initial = intent_mod.IntentState{
        .position = .{ .x=0, .y=0, .z=0 },
        .phase = 0.0,
        .velocity = .{ .x=0, .y=0, .z=0 },
        .potential = 1.0,
    };
