}

test "runtime check balance" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var rt = try Runtime.init(allocator, 4, 64, 4);
    defer rt.deinit();

    const points = [_]symmetry_mod.Vec3{
        .{ .x=1, .y=1, .z=0 },
        .{ .x=-1, .y=1, .z=0 },
        .{ .x=1, .y=-1, .z=0 },
        .{ .x=-1, .y=-1, .z=0 },
    };
    try std.testing.expect(rt.checkBalance(&points, .{ .x=0, .y=0, .z=0 }, 1e-9));
}

test "runtime save and load snapshot" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var rt = try Runtime.init(allocator, 8, 64, 4);
    defer rt.deinit();

    const addr = try rt.store("snapshot test");
    _ = try rt.link(1, 2, "朋友");
    rt.phases.observe(0.0, 1.0);
    _ = rt.phases.releaseOne();

    try rt.saveSnapshot("test_rt_snapshot.json");

    // 新运行时加载
    var rt2 = try Runtime.init(allocator, 8, 64, 4);
    defer rt2.deinit();
    try rt2.loadSnapshot("test_rt_snapshot.json");

    var buf: [64]u8 = [_]u8{0} ** 64;
    const n = try rt2.recall(addr, &buf);
    const actual = std.mem.indexOfScalar(u8, &buf, 0) orelse n;
    try std.testing.expectEqualStrings("snapshot test", buf[0..actual]);
    try std.testing.expect(rt2.relations.relations.count() == 1);
    try std.testing.expect(rt2.phases.reveal_count == 1);

    std.fs.cwd().deleteFile("test_rt_snapshot.json") catch {};
}
