## `src/perception.zig`（完整文件）

```zig
const std = @import("std");

/// 层级：接口层 / 执行层 / 感知层
pub const Layer = enum { interface, execution, perception };

/// 方向
pub const Dir = enum { left, right, inward, outward, both, none };

/// 符号定义
pub const SymbolDef = struct {
    raw: []const u8,
    name: []const u8,
    layer: Layer,
    dir: Dir,
};

/// 符号表：所有已定义符号
pub const TABLE = [_]SymbolDef{
    // 接口层
    .{ .raw = "0<>0", .name = "交互", .layer = .interface, .dir = .both },

    // 执行层：双向
    .{ .raw = "0-<>-0", .name = "相互操作", .layer = .execution, .dir = .both },
    .{ .raw = "0><0", .name = "相挤", .layer = .execution, .dir = .inward },
    .{ .raw = "0>-<0", .name = "相斥", .layer = .execution, .dir = .outward },
    .{ .raw = "0>--<0", .name = "双向向外操作", .layer = .execution, .dir = .outward },
    .{ .raw = "0<->0", .name = "相切", .layer = .execution, .dir = .none },

    // 执行层：单向（方向看减号位置）
    .{ .raw = "0-<0", .name = "向右操作", .layer = .execution, .dir = .right },
    .{ .raw = "0>-0", .name = "向左操作", .layer = .execution, .dir = .left },

    // 感知层（方向看箭头朝向）
    .{ .raw = "0->0", .name = "向右聚焦", .layer = .perception, .dir = .right },
    .{ .raw = "0<-0", .name = "向左聚焦", .layer = .perception, .dir = .left },
};

/// 解析结果
pub const Parsed = struct {
    def: SymbolDef,
    layer: Layer,
    dir: Dir,
};

/// 精确匹配解析
pub fn parse(s: []const u8) ?Parsed {
    for (TABLE) |def| {
        if (std.mem.eql(u8, def.raw, s)) {
            return .{ .def = def, .layer = def.layer, .dir = def.dir };
        }
    }
    return null;
}

/// 判断层级：有没有减号
pub fn layerOf(s: []const u8) ?Layer {
    // 感知层：有箭头但减号不在两端
    if (std.mem.eql(u8, s, "0->0") or std.mem.eql(u8, s, "0<-0")) return .perception;
    // 执行层：有减号
    if (std.mem.indexOfScalar(u8, s, '-') != null) return .execution;
    // 接口层：无减号
    if (std.mem.indexOfScalar(u8, s, '<') != null) return .interface;
    return null;
}

/// 判断方向：执行层看减号位置，感知层看箭头朝向
pub fn dirOf(s: []const u8, layer: Layer) ?Dir {
    switch (layer) {
        .perception => {
            if (std.mem.indexOfScalar(u8, s, '>') != null) return .right;
            if (std.mem.indexOfScalar(u8, s, '<') != null) return .left;
        },
        .execution => {
            // 减号在左 = 向右操作；减号在右 = 向左操作
            const left_minus = std.mem.startsWith(u8, s, "0-");
            const right_minus = std.mem.endsWith(u8, s, "-0");
            if (left_minus and !right_minus) return .right;
            if (right_minus and !left_minus) return .left;
            if (left_minus and right_minus) return .both;
        },
        .interface => return .both,
    }
    return null;
}

/// 通用解析：先判层级，再判方向
pub fn parseGeneric(s: []const u8) ?Parsed {
    const layer = layerOf(s) orelse return null;
    const dir = dirOf(s, layer) orelse return null;

    // 查名称
    var name: []const u8 = "未知";
    for (TABLE) |def| {
        if (std.mem.eql(u8, def.raw, s)) { name = def.name; break; }
    }
    return .{
        .def = .{ .raw = s, .name = name, .layer = layer, .dir = dir },
        .layer = layer,
        .dir = dir,
    };
}

// ========== 测试 ==========

test "exact parse all table entries" {
    for (TABLE) |def| {
        const p = parse(def.raw).?;
        try std.testing.expectEqualStrings(def.name, p.def.name);
        try std.testing.expect(p.layer == def.layer);
    }
}

test "parse unknown returns null" {
    try std.testing.expect(parse("0+++0") == null);
}

test "layer detection" {
    try std.testing.expect(layerOf("0<>0").? == .interface);
    try std.testing.expect(layerOf("0-<0").? == .execution);
    try std.testing.expect(layerOf("0->0").? == .perception);
}

test "direction: execution layer by minus position" {
    // 减号在左 → 向右操作
    try std.testing.expect(dirOf("0-<0", .execution).? == .right);
    // 减号在右 → 向左操作
    try std.testing.expect(dirOf("0>-0", .execution).? == .left);
    // 两边减号 → 双向
    try std.testing.expect(dirOf("0-<>-0", .execution).? == .both);
}

test "direction: perception layer by arrow" {
    try std.testing.expect(dirOf("0->0", .perception).? == .right);
    try std.testing.expect(dirOf("0<-0", .perception).? == .left);
}

test "generic parse" {
    const p1 = parseGeneric("0-<0").?;
    try std.testing.expect(p1.layer == .execution);
    try std.testing.expect(p1.dir == .right);
    try std.testing.expectEqualStrings("向右操作", p1.def.name);

    const p2 = parseGeneric("0->0").?;
    try std.testing.expect(p2.layer == .perception);
    try std.testing.expect(p2.dir == .right);
    try std.testing.expectEqualStrings("向右聚焦", p2.def.name);
}

test "parseGeneric rejects invalid" {
    try std.testing.expect(parseGeneric("0") == null);
    try std.testing.expect(parseGeneric("abc") == null);
}
```

