const std = @import("std");

/// 方向：看箭头总朝向
pub const Direction = enum { left, right, mixed };

/// 变化：单个数是变大还是变小
pub const Change = enum { grow, shrink, mixed };

/// 时间模式：单符号=单次，双符号=连续
pub const TimeMode = enum { once, continuous };

/// 作用：+ 相加，- 相减
pub const Effect = enum { add, sub };

/// 解析结果
pub const Parsed = struct {
    raw: []const u8,
    dir: Direction,
    change: Change,
    time: TimeMode,
    effect: Effect,
};

/// 统计箭头
fn countArrows(s: []const u8) struct { left: u32, right: u32 } {
    var l: u32 = 0;
    var r: u32 = 0;
    for (s) |c| {
        if (c == '<') l += 1;
        if (c == '>') r += 1;
    }
    return .{ .left = l, .right = r };
}

/// 解析符号串
pub fn parse(s: []const u8) ?Parsed {
    if (s.len == 0) return null;

    const arrows = countArrows(s);
    if (arrows.left == 0 and arrows.right == 0) return null;

    // 方向：纯左、纯右、混合
    const dir: Direction = if (arrows.left > 0 and arrows.right == 0)
        .left
    else if (arrows.right > 0 and arrows.left == 0)
        .right
    else
        .mixed;

    // 变化：左箭头=变小，右箭头=变大
    const change: Change = if (dir == .left)
        .shrink
    else if (dir == .right)
        .grow
    else
        .mixed;

    // 时间：数 `+` 和 `-` 的连续段
    var max_run: u32 = 0;
    var cur_run: u32 = 0;
    var cur_char: u8 = 0;
    var effect: Effect = .add;
    for (s) |c| {
        if (c == '+' or c == '-') {
            if (c == cur_char) {
                cur_run += 1;
            } else {
                cur_char = c;
                cur_run = 1;
                effect = if (c == '+') .add else .sub;
            }
            if (cur_run > max_run) max_run = cur_run;
        } else {
            cur_run = 0;
            cur_char = 0;
        }
    }

    const time: TimeMode = if (max_run >= 2) .continuous else .once;

    return .{ .raw = s, .dir = dir, .change = change, .time = time, .effect = effect };
}

// ========== 测试 ==========

test "parse <+<" {
    const p = parse("<+<").?;
    try std.testing.expect(p.dir == .left);
    try std.testing.expect(p.change == .shrink);
    try std.testing.expect(p.time == .once);
    try std.testing.expect(p.effect == .add);
}

test "parse >+>" {
    const p = parse(">+>").?;
    try std.testing.expect(p.dir == .right);
    try std.testing.expect(p.change == .grow);
    try std.testing.expect(p.time == .once);
    try std.testing.expect(p.effect == .add);
}

test "parse >->" {
    const p = parse(">->").?;
    try std.testing.expect(p.dir == .right);
    try std.testing.expect(p.change == .grow);
    try std.testing.expect(p.time == .once);
    try std.testing.expect(p.effect == .sub);
}

test "parse <-<" {
    const p = parse("<-<").?;
    try std.testing.expect(p.dir == .left);
    try std.testing.expect(p.change == .shrink);
    try std.testing.expect(p.time == .once);
    try std.testing.expect(p.effect == .sub);
}

test "parse >-->" {
    const p = parse(">-->").?;
    try std.testing.expect(p.dir == .right);
    try std.testing.expect(p.change == .grow);
    try std.testing.expect(p.time == .continuous);
    try std.testing.expect(p.effect == .sub);
}

test "parse <++<" {
    const p = parse("<++<").?;
    try std.testing.expect(p.dir == .left);
    try std.testing.expect(p.change == .shrink);
    try std.testing.expect(p.time == .continuous);
    try std.testing.expect(p.effect == .add);
}

test "parse mixed <++>" {
    const p = parse("<++>").?;
    try std.testing.expect(p.dir == .mixed);
    try std.testing.expect(p.change == .mixed);
    try std.testing.expect(p.time == .continuous);
    try std.testing.expect(p.effect == .add);
}

test "parse mixed >--<" {
    const p = parse(">--<").?;
