    try std.testing.expect(p.change == .mixed);
    try std.testing.expect(p.time == .continuous);
    try std.testing.expect(p.effect == .sub);
}

test "parse invalid" {
    try std.testing.expect(parse("") == null);
    try std.testing.expect(parse("++") == null);
    try std.testing.expect(parse("abc") == null);
}
