```zig
const std = @import("std");
const perception_mod = @import("perception.zig");

/// 向量层输出的候选：物体 + 相似度 + 方向
pub const Candidate = struct {
    label: []const u8,
    similarity: f64,
    direction: perception_mod.Dir, // 左/右/中间
};

/// 符号层输出的动作
pub const Action = struct {
    kind: enum { focus, grab, retract },
    dir: perception_mod.Dir,
    reason: []const u8,
};

/// 符号层规则：从候选里选一个，输出动作序列
pub fn planActions(
    allocator: std.mem.Allocator,
    candidates: []const Candidate,
    threshold: f64,
) !std.ArrayList(Action) {
    var actions = std.ArrayList(Action).init(allocator);

    // 1. 筛选：相似度过阈值
    var best: ?Candidate = null;
    for (candidates) |c| {
        if (c.similarity < threshold) continue;
        if (best == null or c.similarity > best.?.similarity) {
            best = c;
        }
    }

    if (best == null) {
        try actions.append(.{ .kind = .retract, .dir = .none, .reason = "无候选过阈值，回退" });
        return actions;
    }

    const target = best.?;

    // 2. 聚焦：方向看候选位置
    try actions.append(.{
        .kind = .focus,
        .dir = target.direction,
        .reason = "相似度最高，聚焦目标",
    });

    // 3. 抓取：抓力符号 >+<
    try actions.append(.{
        .kind = .grab,
        .dir = target.direction,
        .reason = "抓力 >+<，持续增强",
    });

    // 4. 如果相似度不够高，加弹射回退
    if (target.similarity < 0.9) {
        try actions.append(.{
            .kind = .retract,
            .dir = .none,
            .reason = "相似度低于 0.9，弹射 ! 回退",
        });
    }

    return actions;
}

// ========== 测试 ==========

test "plan picks highest similarity" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const candidates = [_]Candidate{
        .{ .label = "杯子", .similarity = 0.9, .direction = .left },
        .{ .label = "碗", .similarity = 0.7, .direction = .right },
        .{ .label = "瓶子", .similarity = 0.5, .direction = .right },
    };

    var actions = try planActions(allocator, &candidates, 0.6);
    defer actions.deinit();

    // 杯子相似度最高，先聚焦左，再抓
    try std.testing.expect(actions.items.len >= 2);
    try std.testing.expect(actions.items[0].kind == .focus);
    try std.testing.expect(actions.items[0].dir == .left);
    try std.testing.expect(actions.items[1].kind == .grab);
}

test "plan retracts when no candidate" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const candidates = [_]Candidate{
        .{ .label = "杯子", .similarity = 0.3, .direction = .left },
    };

    var actions = try planActions(allocator, &candidates, 0.6);
    defer actions.deinit();

    try std.testing.expect(actions.items.len == 1);
    try std.testing.expect(actions.items[0].kind == .retract);
}

test "plan adds retract when similarity low" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const candidates = [_]Candidate{
        .{ .label = "杯子", .similarity = 0.7, .direction = .left },
    };

    var actions = try planActions(allocator, &candidates, 0.6);
    defer actions.deinit();

    // 相似度 0.7 过阈值但低于 0.9，加弹射回退
    try std.testing.expect(actions.items.len == 3);
    try std.testing.expect(actions.items[2].kind == .retract);
}
