```zig
/// 三角数节点：可引用、可召唤的身份
const 三角数节点 = struct {
    id: u64,              // 身份
    n: u32,               // 第几个三角数
    value: u64,           // 三角数值
    被召唤次数: u64 = 0,
    可作注意力转换: bool = true,
};

/// 三角数内存：和意图流一体化，不另开一套
const 三角数内存 = struct {
    节点表: std.AutoHashMap(u64, 三角数节点),

    /// 召唤：按 id 取三角数，作为注意力转换选项
    pub fn 召唤(self: *三角数内存, id: u64) ?三角数节点 {
        return self.节点表.get(id);
    }

    /// 思维选择：从可用三角数里选一个作为转换
    pub fn 选择转换(self: *三角数内存, n: u32) ?三角数节点 {
        var it = self.节点表.valueIterator();
        while (it.next()) |node| {
            if (node.n == n and node.可作注意力转换) return node.*;
        }
        return null;
    }
};
```

