pub fn 注册归属运算(
    self: *Runtime,
    归属: anchor_mod.归属,
    func: anchor_mod.运算函数,
) !void {
    try self.anchor_ops.注册(归属, func);
}

/// 绑定时间线并执行归属运算
pub fn 执行归属(
    self: *Runtime,
    归属: anchor_mod.归属,
    allocator: std.mem.Allocator,
) !f64 {
