/// 执行一个话题锚点绑定的意识单元链
pub fn 执行锚点意识链(
    self: *Runtime,
    锚点: anchor_mod.目标锚点,
    input: f64,
) !f64 {
    var result = input;
    for (锚点.意识单元链) |单元| {
        result = self.执行意识单元(单元, result);
    }
    return result;
}
